(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('shaper','Shaper combines shape and the agent suffix -er; it names a person or machine that gives form to an idea or object.',C('shaper.s1','塑形者；成形工具','The wood shaper cut a smooth curve into the cabinet door without splitting the grain.','木材成形机在柜门上切出平滑曲线，没有劈裂木纹。','The wood shaper cut a curve / into the cabinet door / without splitting the grain.','shaper.s1 指赋予物体或想法形状的人或机器。','机器把木板加工成所需形状。'),M('The wood shaper left the board unchanged because it never touched or formed the wood.','The wood shaper cut a curve into the board.','完全没有加工木材就没有发挥成形作用。','meaning'),[q('What did the wood shaper cut into the door?','a smooth curve','a broken pane of glass','a metal sheath','机器在柜门上切出一条平滑曲线。',1,'context'),q('What did the machine avoid doing?','splitting the wood grain','shaping the curve','cutting the cabinet door','加工时木纹没有被劈裂。',1,'context'),q('What is a shaper?','a person or machine that gives form to something','a person who sells company shares','a sharp fragment of glass','shaper 指为物体或想法塑形的人或机器。',1,'meaning'),q('Which tool is a shaper?','a machine that cuts a board into a curved profile','a shelf used only to store boards','a sensor that measures room heat','能把木板加工成曲线轮廓的机器是 shaper。',1,'context')]);
P('shard','Shard is from Old English sceard, “piece cut off,” related to scieran (“cut”); it means a small sharp fragment of broken glass, pottery, or rock.',C('shard.s1','碎片；碎块','A shard of blue pottery lay beside the path, so the gardener marked the spot before anyone stepped on it.','一块蓝色陶器碎片落在小路旁，园丁先标记了位置，以免有人踩到。','A shard of blue pottery lay / beside the path / so the gardener marked it.','shard.s1 指从玻璃、陶器或岩石等物体上破裂下来的尖锐小块。','园丁标记尖锐陶片以防踩伤。'),M('The gardener called the intact clay pot a shard even though it had not broken into pieces.','The gardener called the sharp broken piece of pottery a shard.','完整陶罐不是破裂后形成的碎片。','meaning'),[q('What color was the pottery shard?','blue','green','silver','路边的陶器碎片是蓝色的。',1,'context'),q('Why did the gardener mark the spot?','to stop someone stepping on the sharp fragment','to sell the intact pot','to sharpen a garden tool','标记位置是为了避免有人踩到尖锐陶片。',1,'context'),q('What is a shard?','a small sharp piece broken off a larger object','an intact ceramic bowl','a soft cloth worn over the shoulders','shard 指从较大物体破裂下来的尖锐小块。',1,'meaning'),q('Which item is a shard?','a jagged piece of glass from a broken window','a complete uncracked window pane','a wool shawl','破窗上掉下来的锯齿状玻璃块是 shard。',1,'context')]);
P('share','Share comes from Old English scearu (“a cutting, division”); it can mean use something with others, have a quality in common, or one portion/company ownership unit.',[C('share.s1','分享；共用；分担','The neighbors share one rain barrel and take turns using its water for their gardens.','邻居们共用一个雨水桶，轮流取水浇灌花园。','The neighbors share one rain barrel / and take turns / using its water.','share.s1 指与他人共同使用、分担或给予一部分。','大家轮流使用同一水桶。'),C('share.s2','有同样的看法或特征','Both reviewers share the view that the final chapter needs clearer evidence.','两位评论者都认为最后一章需要更清楚的证据。','Both reviewers share the view / that the final chapter / needs clearer evidence.','share.s2 指与另一人有相同观点或特征。','两位评论者有相同看法。'),C('share.s3','一份；股份','Nia bought a share in the worker-owned bakery and now receives part of its annual profit.','妮娅购买了这家员工所有面包店的一份股份，现在能分得部分年度利润。','Nia bought a share / in the worker-owned bakery / and receives part of its profit.','share.s3 作名词，可指一份或公司所有权单位。','购买一股意味着拥有部分企业权益。')],M('The neighbors share the rain barrel by locking it so that only one household can ever use the water.','The neighbors share the rain barrel by taking turns using its water.','锁起来不让其他邻居使用，不是共同使用。','meaning'),[q('What do the neighbors share?','one rain barrel','a company profit','one reviewer’s opinion','邻居们共用一个雨水桶。',1,'context'),q('What view do both reviewers share?','the last chapter needs clearer evidence','the first chapter should be removed','the bakery should close','两位评论者都认为末章需要更清楚的证据。',2,'context'),q('What did Nia buy in the bakery?','a share representing part ownership','a sharp shard of pottery','a wool cover for her shoulders','妮娅购买了面包店的一份股份。',3,'context'),q('What does share mean in “share one rain barrel”?','use something jointly with others','own a single portion of company stock','have the same opinion','此处 share 指共同使用。',1,'meaning')]);
P('shared','Shared is the past participle of share and an adjective; it can mean available to multiple people, belonging to a group, or mutual between people.',[C('shared.s1','共用的；共有的','The tenants use a shared laundry room on the ground floor, with a posted schedule for the machines.','租户们共用一楼的洗衣房，墙上贴着机器使用时间表。','The tenants use a shared laundry room / with a posted schedule / for the machines.','shared.s1 指供多个人使用或享有的。','租户共同使用洗衣房。'),C('shared.s2','集体的；共同承担的','The cleanup was a shared responsibility, so every household sent one volunteer to clear the riverbank.','清理工作由大家共同负责，因此每户都派了一名志愿者清理河岸。','The cleanup was a shared responsibility / so each household / sent a volunteer.','shared.s2 指属于群体或由群体共同完成的。','每户承担一部分工作。'),C('shared.s3','相互的；彼此的','Their shared respect for the coach helped the rival players cooperate after the final whistle.','他们彼此尊重同一位教练，这帮助两名对手在终场哨后合作。','Their shared respect for the coach / helped the rivals / cooperate after the match.','shared.s3 指两人或多人彼此拥有或表达的感情、态度。','双方都尊重同一位教练。')],M('The cleanup was a shared responsibility, but only one household was allowed to help and all others were excluded.','The cleanup was a shared responsibility carried by every household.','排斥其他家庭不符合共同承担。','meaning'),[q('Where was the shared laundry room?','on the ground floor','inside the coach’s office','at the river mouth','租户们共用一楼的洗衣房。',1,'context'),q('How did households take part in cleanup?','each sent one volunteer','one household did everything while others were excluded','they all ignored the riverbank','每户都派了一名志愿者参加清理。',2,'context'),q('What does shared mean in “shared respect”?','felt by both people toward the same person','available for only one person to use','owned by a single household','shared respect 指双方都怀有的尊重。',3,'meaning'),q('What does shared mean in “shared laundry room”?','used by more than one tenant','reserved for one tenant only','a room no one may enter','shared laundry room 指多名租户共用的洗衣房。',1,'meaning')]);
P('shareholder','Shareholder combines share and holder; it means a person or institution that owns shares and therefore part of a company.',C('shareholder.s1','股票持有者；股东','Each shareholder received an annual report explaining the company’s earnings and plans for a new branch.','每位股东都收到年度报告，里面说明了公司的收益和开设新分店的计划。','Each shareholder received a report / explaining company earnings / and plans for a branch.','shareholder.s1 指持有公司股份、因而拥有公司部分权益的人或机构。','股东收到有关公司财务的报告。'),M('A shareholder owned part of the company despite holding no shares and having no ownership interest.','A shareholder owned part of the company by holding its shares.','没有股份也没有所有权的人不是 shareholder。','meaning'),[q('What did each shareholder receive?','an annual report','a wool shawl','a sharpener','每位股东收到一份年度报告。',1,'context'),q('What did the report explain?','company earnings and plans for a new branch','the color of a pottery shard','the schedule for a shared laundry','报告说明了公司收益和开新店计划。',1,'context'),q('What is a shareholder?','a person or institution that owns company shares','a customer who buys one loaf of bread','a person who sharpens tools','shareholder 指拥有公司股份的人或机构。',1,'meaning'),q('Which person is a shareholder?','someone who owns stock in a corporation','someone who rents a room from a corporation','someone who uses its shared laundry','持有公司股票的人是 shareholder。',1,'context')]);
P('shark','Shark is recorded in English in the 16th century; its earlier origin is uncertain. It can name a large sea fish or a person who cheats others for money.',[C('shark.s1','鲨鱼','A shark circled the reef, and the lifeguard asked swimmers to leave the water calmly.','一条鲨鱼在礁石周围游动，救生员请游泳者冷静地离开水面。','A shark circled the reef / so the lifeguard / asked swimmers to leave.','shark.s1 指海中有锋利牙齿的大型鱼类。','救生员发现海中有鲨鱼。'),C('shark.s2','骗子；贪心的商人','The loan shark charged desperate borrowers illegal fees and threatened them when they could not pay.','高利贷骗子向走投无路的借款人收取非法费用，并在他们无力偿还时威胁他们。','The loan shark charged illegal fees / and threatened borrowers / who could not pay.','shark.s2 指通过欺诈或剥削骗取他人钱财的人。','放高利贷者利用借款人的困境。')],M('The loan shark protected borrowers by charging no fees and forgiving every debt.','The loan shark exploited borrowers with illegal fees and threats.','免除债务并保护借款人不是剥削性骗子的行为。','meaning'),[q('What did the lifeguard see near the reef?','a shark','a sheepfold','a shears tool','救生员发现礁石附近有一条鲨鱼。',1,'context'),q('How did the loan shark treat borrowers?','charged illegal fees and threatened them','forgave every debt','provided free shelter','放高利贷者收非法费用并威胁借款人。',2,'context'),q('What does shark mean in “a shark circled the reef”?','a large fish living in the sea','a dishonest lender','a person who holds company shares','礁石句中的 shark 指海里的大型鱼。',1,'meaning'),q('What does loan shark mean?','a person who lends money exploitatively or dishonestly','a marine fish near a reef','a bank employee who cancels fees','loan shark 指剥削或欺诈性放贷者。',2,'meaning')]);
P('sharp','Sharp comes from Old English scearp; it can mean having a cutting edge, sudden or intense, quick to understand, or exactly at a stated time.',[C('sharp.s1','锋利的；尖的','Use the sharp kitchen knife to slice the ripe tomato, keeping your fingers clear of the blade.','用锋利的菜刀切熟番茄，手指要避开刀刃。','Use the sharp kitchen knife / to slice the tomato / keeping fingers clear.','sharp.s1 指边缘或尖端薄而能切割的。','刀刃能切开番茄。'),C('sharp.s2','急剧的；强烈的；刺耳的','The temperature took a sharp drop after the cold front reached the valley.','冷锋抵达山谷后，气温急剧下降。','The temperature took a sharp drop / after the cold front / reached the valley.','sharp.s2 可指突然且幅度大的变化或感官上刺耳、强烈的感觉。','气温骤降。'),C('sharp.s3','敏锐的；精明的','A sharp observer noticed that the second signature was written in different ink.','一位观察敏锐的人注意到第二个签名用的是不同墨水。','A sharp observer noticed / the second signature / used different ink.','sharp.s3 指能迅速注意或理解细节的。','观察者发现细微的墨水差异。'),C('sharp.s4','（时刻）整；准','The interview starts at nine sharp, so candidates should arrive before the hour.','面试准九点开始，因此候选人应在整点前到达。','The interview starts at nine sharp / so candidates / should arrive early.','sharp.s4 放在时间后表示恰好在所说时刻。','九点整准时开始。')],M('The interview begins at nine sharp, which means candidates may arrive any time later that morning.','The interview begins at exactly nine o’clock.','nine sharp 指恰好九点，不是当天上午任意时间。','meaning'),[q('What tool should be used to slice the tomato?','the sharp kitchen knife','a blunt wooden spoon','a wool shawl','要用锋利的菜刀切番茄。',1,'context'),q('What happened after the cold front arrived?','the temperature dropped sharply','the temperature stayed exactly the same','the interview began early','冷锋抵达后气温急剧下降。',2,'context'),q('Why was the observer called sharp?','they quickly noticed different ink in the signature','they used a knife to cut the paper','they arrived at nine o’clock','观察者敏锐地发现了签名墨水不同。',3,'meaning'),q('What does nine sharp mean?','exactly at nine o’clock','any time before noon','nine minutes after nine','nine sharp 表示恰好九点整。',4,'meaning')]);
P('sharpen','Sharpen combines sharp and -en; it can mean make a blade pointed or make a quality, image, or feeling more intense.',[C('sharpen.s1','使锋利；削尖','The cook sharpened the paring knife on a whetstone before peeling the basket of apples.','厨师在削一篮苹果之前，先用磨刀石磨利了削皮刀。','The cook sharpened the paring knife / on a whetstone / before peeling the apples.','sharpen.s1 指使刀具或工具的刃口变锋利。','磨刀石使刀刃更锋利。'),C('sharpen.s2','使更加敏锐；增强','The close election sharpened public interest in every count from the remaining districts.','势均力敌的选举使公众对剩余地区的每一项计票都更加关注。','The close election sharpened public interest / in every count / from remaining districts.','sharpen.s2 指使感情、品质或图像变得更强烈、鲜明。','选情激烈使关注度上升。')],M('The cook sharpened the knife by rubbing it against a soft cloth until its edge became dull.','The cook sharpened the knife on a whetstone until its edge became keen.','把刀刃磨钝与使其锋利相反。','meaning'),[q('What did the cook sharpen?','a paring knife','a sheepfold gate','a shareholder report','厨师磨利了削皮刀。',1,'context'),q('What did the close election sharpen?','public interest in the remaining counts','the knife’s blade','the color of the tomato','势均力敌的选举提高了公众对剩余计票的关注。',2,'context'),q('What does sharpen mean in the kitchen example?','make a blade keen or pointed','make a feeling less intense','divide a company into shares','厨房句中的 sharpen 指磨利刀刃。',1,'meaning'),q('What does sharpen mean in the election example?','make interest more intense','cut something with a sharp blade','put a knife into its sheath','选举句中的 sharpen 指使公众关注增强。',2,'meaning')]);
P('sharpener','Sharpener is formed from sharpen and -er; it names an instrument used to make a point or edge sharp.',C('sharpener.s1','研磨工具；削尖器','The student used a small pencil sharpener to make a clean point before labeling the diagram.','学生用小削笔器把铅笔削尖，然后给图表标注。','The student used a pencil sharpener / to make a clean point / before labeling.','sharpener.s1 指用来使物品尖端或刃口变锋利的工具。','削笔器使铅笔尖细。'),M('The student used a sharpener to erase the pencil marks without changing the pencil’s point.','The student used a sharpener to make the pencil point sharp.','sharpener 用于削尖，而不是擦除笔迹。','meaning'),[q('What did the student sharpen?','a pencil','a wool blanket','a tomato','学生用削笔器削尖铅笔。',1,'context'),q('Why did the student sharpen it?','to label the diagram neatly','to divide the diagram into shares','to shave a sheep','学生削好铅笔后要给图表标注。',1,'context'),q('What is a sharpener?','a tool for making a point or edge sharp','a cover that protects a blade','a person who owns company shares','sharpener 指把尖端或刃口磨锋利的工具。',1,'meaning'),q('Which item is a sharpener?','a small device that forms a pointed pencil tip','a rubber eraser that removes graphite','a sheath that covers a knife','能把铅笔削成尖头的小工具是 sharpener。',1,'context')]);
P('sharper','Sharper is the comparative form of sharp; as a noun it means a swindler, especially a dishonest card player.',C('sharper.s1','欺诈者；老千','The sharper marked the cards and cheated unsuspecting players during the late-night game.','这名老千在深夜牌局中做了记号，欺骗毫无戒心的玩家。','The sharper marked the cards / and cheated unsuspecting players / during the game.','sharper.s1 作名词指欺诈者，尤其是牌局中的骗子。','对方做记号作弊。'),M('The sharper played fairly, kept the cards unmarked, and warned the other players about cheating.','The sharper marked the cards and cheated the other players.','公平游戏并揭发作弊不符合欺诈者的身份。','meaning'),[q('What did the sharper do to the cards?','marked them','sharpened them with a whetstone','put them inside a sheath','老千在牌上做了记号。',1,'context'),q('Whom did the sharper cheat?','unsuspecting players','the referee at a football match','a shareholder at a meeting','老千欺骗了毫无戒心的玩家。',1,'context'),q('What is a sharper in this entry?','a swindler, especially a dishonest card player','a tool for sharpening a pencil','a person with excellent eyesight only','sharper 名词指骗子，尤其是牌局中的老千。',1,'meaning'),q('Which person is a sharper?','a card player who secretly marks cards to cheat','a player who follows every rule','a dealer who exposes a marked deck','暗中在牌上做记号作弊的人是 sharper。',1,'context')]);
P('sharply','Sharply is formed from sharp and -ly; it means quickly and to a large degree, or in a harsh, critical tone.',[C('sharply.s1','急剧地；猛然地','After the factory closed, local employment fell sharply within a few months.','工厂关闭后，几个月内当地就业率急剧下降。','Local employment fell sharply / within a few months / after the factory closed.','sharply.s1 指迅速且幅度很大地变化。','就业率在短期内大幅下降。'),C('sharply.s1','尖锐地；严厉地','The editor replied sharply when the reporter repeated an accusation that had already been disproved.','记者重复一项已被证伪的指控时，编辑尖锐地作出回应。','The editor replied sharply / when the reporter repeated / a disproved accusation.','sharply.s1 也可指以严厉或批评的语气说话。','编辑用尖锐语气回应。')],M('Employment fell sharply, meaning the number of jobs changed only slightly over several decades.','Employment fell sharply, meaning it declined quickly and substantially.','sharply 在此表示快速且大幅下降，不是轻微缓慢变化。','meaning'),[q('What happened to local employment after the factory closed?','it fell sharply','it rose slowly','it stayed exactly level','工厂关闭后当地就业率急剧下降。',1,'context'),q('Why did the editor reply sharply?','the reporter repeated a disproved accusation','the reporter apologized and withdrew it','the editor received a shawl','记者重复了已被证伪的指控，编辑因此尖锐回应。',1,'context'),q('What does sharply mean about employment?','quickly and to a large degree','in a gentle and gradual way','at exactly nine o’clock','就业率句中的 sharply 指快速且大幅地。',1,'meaning'),q('What does sharply mean about the editor’s reply?','in a harsh, critical tone','in a cheerful whisper','with no spoken response','编辑的 sharply 指以尖锐、严厉的语气回应。',1,'meaning')]);
P('shatter','Shatter is recorded in Middle English; its earlier origin is uncertain. It means break suddenly into fragments or destroy a hope or deeply shock someone.',[C('shatter.s1','粉碎；破碎','The dropped glass shattered on the stone floor, leaving small pieces beneath the table.','玻璃杯掉在石地上摔碎了，桌子下面留下许多小碎片。','The dropped glass shattered / on the stone floor / leaving small pieces.','shatter.s1 指突然破裂成许多小碎片。','玻璃杯落地后碎裂。'),C('shatter.s2','使破灭；使震惊','The audit findings shattered the board’s confidence in the company’s safety claims.','审计结果使董事会对公司的安全声明彻底失去信心。','The audit findings shattered confidence / in the company’s / safety claims.','shatter.s2 指摧毁希望、信心或使人深受震动。','审计发现动摇了董事会的信心。')],M('The dropped glass shattered into pieces, but it remained whole and unbroken on the floor.','The dropped glass shattered into small pieces on the floor.','完整无损与碎裂成片相矛盾。','meaning'),[q('Where did the glass shatter?','on the stone floor','inside a wool shawl','in the shared laundry room','玻璃杯摔在石地上碎裂。',1,'context'),q('What did the audit findings shatter?','the board’s confidence in the safety claims','the glass on the floor','the company’s office window','审计结果摧毁了董事会对安全声明的信心。',2,'context'),q('What does shatter mean in the glass example?','break suddenly into fragments','make something more pointed','share one object with others','玻璃句中的 shatter 指突然碎裂。',1,'meaning'),q('What does shatter mean in the audit example?','destroy confidence or deeply shock','physically cut something with a knife','store tools in a shed','审计句中的 shatter 指彻底动摇信心。',2,'meaning')]);
P('shave','Shave comes from Old English scafan (“scrape, shave”); it can mean cut hair close to the skin, reduce a quantity slightly, or an act of shaving.',[C('shave.s1','剃；刮毛发','He shaved his beard before the passport photograph so his face would be clearly visible.','他在拍护照照片前刮掉胡须，好让脸部清楚可见。','He shaved his beard / before the passport photograph / so his face was visible.','shave.s1 指把毛发剪得非常贴近皮肤。','刮胡子露出面部。'),C('shave.s2','削减一点点','The builders shaved two days off the schedule by prefabricating the stair sections.','建筑工人通过预制楼梯段，把工期缩短了两天。','The builders shaved two days off the schedule / by prefabricating / stair sections.','shave.s2 指小幅减少数字、时间或数量。','工期缩短两天。'),C('shave.s3','刮脸；剃须','After his morning shave, Malik rinsed the razor and put it back in its case.','早晨刮完脸后，马利克冲洗剃须刀并把它放回盒子。','After his morning shave / Malik rinsed the razor / and put it away.','shave.s3 作名词指一次剃须或刮脸。','剃须后冲洗剃刀。')],M('The builders shaved two days off the schedule by adding two days to the project.','The builders shaved two days off the schedule by finishing two days sooner.','增加工期不能算削减工期。','meaning'),[q('Why did he shave before the passport photograph?','so his face would be clearly visible','to hide his face beneath a shawl','to shorten the construction schedule','他拍照前刮胡子，让脸清楚可见。',1,'context'),q('How much time did the builders shave off the schedule?','two days','two months','two hours','工人把工期缩短了两天。',2,'context'),q('What does shave mean as a noun in “morning shave”?','an act of shaving','a thick wool garment','a share of company ownership','morning shave 指一次早晨剃须。',3,'meaning'),q('What does shave mean in “shaved two days off”?','reduced the schedule by a small amount','cut hair close to the skin','made the schedule longer','此处 shave 指把工期略微缩短。',2,'meaning')]);
P('shawl','Shawl came into English from Persian shāl, probably through South Asian languages; it is a piece of cloth worn over the head, shoulders, or arms.',C('shawl.s1','披肩；围巾','A wool shawl covered her shoulders during the chilly evening concert in the open courtyard.','在露天庭院举行的寒冷晚间音乐会上，一条羊毛披肩盖住了她的肩膀。','A wool shawl covered her shoulders / during the chilly evening / concert.','shawl.s1 指披在头部、肩膀或手臂上的一块布。','披肩用于保暖。'),M('She wrapped a shawl around her shoulders even though she was carrying no cloth at all.','She wrapped a wool shawl around her shoulders.','没有布料就不能披上 shawl。','meaning'),[q('What material was the shawl made of?','wool','glass','steel','披肩是羊毛制的。',1,'context'),q('When did she wear it?','during a chilly evening concert','during a hot noon swim','while sharpening a knife','她在寒冷的晚间音乐会上披着羊毛披肩。',1,'context'),q('What is a shawl?','a piece of cloth worn over the head or shoulders','a small sharp fragment of pottery','a tool for cutting branches','shawl 指披在头部或肩膀上的布。',1,'meaning'),q('Which item is a shawl?','a woven wrap draped over someone’s shoulders','a blade cover fitted to a knife','a paper share certificate','披在肩上的织物是 shawl。',1,'context')]);
P('she','She is the feminine third-person singular pronoun, from Old English hēo; it can also refer to a ship, country, or car in some traditional or literary usage.',[C('she.s1','她（主格）','After Dr. Chen presented the plan, she answered questions from the students.','陈博士介绍完计划后，她回答了学生们的问题。','After Dr. Chen presented the plan / she answered / questions from students.','she.s1 用作主语，指前文提到的女性或雌性动物。','she 指代前句中的陈博士。'),C('she.s2','她（指船、国家等，文学）','The old captain called the sailing ship “she” and said she had weathered many storms.','老船长把那艘帆船称作“她”，并说她经历过许多风暴。','The captain called the ship “she” / and said she had / weathered many storms.','she.s2 在某些传统或文学用法中可指船、国家或汽车。','she 在此指帆船。')],M('Dr. Chen explained the plan and then he answered the students, although Chen was the woman named in the passage.','Dr. Chen explained the plan and then she answered the students.','指代已明确为女性的陈博士时应使用 she。','meaning'),[q('Who answered the students’ questions?','Dr. Chen','the old captain','the sailing ship’s builder','陈博士回答了学生的问题。',1,'context'),q('What did the captain call the sailing ship?','“she”','“he” only','“they” as a plural crew','船长把帆船称作 she。',2,'context'),q('What does she refer to in the first example?','the woman Dr. Chen','the students as a group','the plan','第一句 she 指女性陈博士。',1,'meaning'),q('Why might a captain use she for a ship?','traditional or literary usage sometimes treats a ship as she','a ship is literally a human woman','the pronoun always means a female captain','传统或文学用法有时用 she 指船。',2,'meaning')]);
P('shear','Shear comes from Old English scieran (“cut”); it can mean cut wool or trim plants, break under sideways force, or a large cutting tool/force.',[C('shear.s1','剪羊毛；修剪','The farmer shears the sheep each spring before the weather becomes too warm.','农夫每年春天在天气变得太热之前给羊剪毛。','The farmer shears the sheep / each spring / before hot weather.','shear.s1 作动词指剪掉羊毛或修剪植物。','羊毛在春季被剪下。'),C('shear.s2','（受剪切力）断裂','The metal bolt sheared under the sideways pressure when the heavy gate slammed shut.','沉重大门猛然关闭时，金属螺栓在横向压力下断裂。','The metal bolt sheared / under sideways pressure / as the gate slammed.','shear.s2 作动词指材料在强横向压力下断裂。','螺栓承受横向力后断开。'),C('shear.s3','大剪刀；剪切力','The mechanic used heavy shears to cut the sheet metal into narrow strips.','技工用大型剪剪刀把金属薄板切成窄条。','The mechanic used heavy shears / to cut sheet metal / into narrow strips.','shear.s3 可指大型剪刀，也可指横向剪切力。','大型剪刀剪切金属薄板。')],M('The farmer sheared the sheep by leaving its wool untouched and merely weighing the animal.','The farmer sheared the sheep by cutting off its wool.','只称重并未剪掉羊毛。','meaning'),[q('When does the farmer shear the sheep?','each spring before hot weather','each winter after the first snow','only after the sheep loses its wool naturally','农夫每年春天给羊剪毛。',1,'context'),q('What caused the bolt to shear?','sideways pressure when the gate slammed','a gentle vertical lift','the sheep’s wool','大门猛关时的横向压力使螺栓断裂。',2,'context'),q('What did the mechanic use to cut sheet metal?','heavy shears','a wool shawl','a pencil sharpener','技工用大型剪剪刀切金属薄板。',3,'context'),q('What does shear mean in the bolt example?','break apart under strong sideways pressure','trim wool from an animal','cover a blade with a sheath','螺栓句中的 shear 指在横向压力下断裂。',2,'meaning')]);
P('shears','Shears is the plural form of shear; it names a large cutting tool like scissors, used for grass, branches, metal, or hair.',C('shears.s1','大剪刀；长剪','The gardener used long-handled shears to trim the hedge without bending down.','园丁用长柄大剪刀修剪树篱，不必弯腰。','The gardener used long-handled shears / to trim the hedge / without bending.','shears.s1 指用于剪草、树枝、金属或头发的大型剪刀。','长柄剪刀修整树篱。'),M('The gardener used shears to water the hedge by pouring a bucket over the branches.','The gardener used shears to cut and trim the hedge.','shears 用于剪切，不能通过浇水修剪树枝。','meaning'),[q('What did the gardener trim?','the hedge','a company’s shares','a sheepfold roof','园丁用大剪刀修剪树篱。',1,'context'),q('Why were the shears long-handled?','so the gardener could trim without bending down','so they could be worn as a shawl','so they could measure rainfall','长柄让园丁不必弯腰修剪。',1,'context'),q('What are shears?','large scissors used for cutting','a cover for a sword blade','a small fragment of glass','shears 指用于剪切的大型剪刀。',1,'meaning'),q('Which tool is shears?','long-handled cutters for trimming branches','a watering can for shrubs','a knife cover made of leather','修剪树枝的长柄剪刀是 shears。',1,'context')]);
P('sheath','Sheath comes from Old English scēath, “covering”; it can mean a protective cover for a blade or a thin layer of tissue or plant material around a part.',[C('sheath.s1','鞘；刀鞘','The hiker slid the knife into its leather sheath before climbing over the rocks.','徒步者翻越岩石前把刀插回皮刀鞘。','The hiker slid the knife / into its leather sheath / before climbing.','sheath.s1 指保护刀、剑或矛刃的外套。','刀鞘保护锋利刀刃。'),C('sheath.s2','（植物或解剖上的）鞘','A leaf sheath wrapped around the lower part of the grass stem.','叶鞘包裹着草茎的下部。','A leaf sheath wrapped around / the lower part / of the grass stem.','sheath.s2 指包绕茎或器官的一层薄组织或叶基。','叶鞘包住草茎。')],M('The knife’s sheath exposed the sharp blade and offered no protective covering.','The knife’s sheath covered the blade and protected its edge.','暴露刀刃而不作保护，说明那不是护鞘。','meaning'),[q('What material was the hiker’s sheath made of?','leather','glass','grass','徒步者的刀鞘是皮制的。',1,'context'),q('What did the leaf sheath wrap around?','the lower part of the grass stem','the blade of the hiker’s knife','a shareholder certificate','叶鞘包裹草茎下部。',2,'context'),q('What is a sheath in the knife example?','a protective cover for a blade','a sharp piece of broken glass','a large pair of scissors','刀的 sheath 是保护刀刃的鞘。',1,'meaning'),q('What is a leaf sheath?','a layer of plant tissue wrapping around part of a stem','a leather cover for a knife','a seed inside a tree trunk','leaf sheath 指包绕茎部的植物组织。',2,'meaning')]);
P('sheathe','Sheathe is formed from sheath and the verbal suffix -e; it means slide a blade into its sheath or cover something with a protective outer layer.',[C('sheathe.s1','插入鞘中','The guard sheathed his sword as soon as the ceremony ended.','仪式一结束，卫兵就把剑插入剑鞘。','The guard sheathed his sword / as soon as / the ceremony ended.','sheathe.s1 指把刀或剑插回鞘中。','剑被收回剑鞘。'),C('sheathe.s2','覆盖；包住','Workers sheathed the exposed cable in a tough rubber layer to protect it from rain.','工人用坚韧橡胶层包住裸露电缆，以防雨水侵蚀。','Workers sheathed the cable / in a tough rubber layer / to protect it from rain.','sheathe.s2 指用保护性外层包裹某物。','橡胶层保护电缆。')],M('Workers sheathed the cable by removing its protective rubber cover and leaving the wires exposed.','Workers sheathed the cable in a protective rubber layer.','去掉保护层并露出电线与 sheathe 相反。','meaning'),[q('When did the guard sheathe the sword?','when the ceremony ended','before the sword was drawn','after the cable was repaired','仪式结束时卫兵把剑插回剑鞘。',1,'context'),q('What covered the cable?','a tough rubber layer','a leather sword sheath','a wool shawl','工人用坚韧橡胶层包住电缆。',2,'context'),q('What does sheathe mean in the sword example?','put a blade back into its sheath','remove a protective cover','sharpen a blade','剑的例句中 sheathe 指把剑插回鞘中。',1,'meaning'),q('What does sheathe mean in the cable example?','cover something with a protective outer layer','expose its inner wires','send it to another country','电缆句中的 sheathe 指用保护外层包裹。',2,'meaning')]);
P('shed','Shed has distinct verb and noun histories: the verb is Old English scēadan (“divide, separate”), while the storage-building noun is attested in Middle English; the word can mean lose/emit, get rid of, or a simple storage building.',[C('shed.s1','脱落；蜕；掉','The maple shed its leaves in October, covering the path with red and gold.','枫树在十月落叶，红金色的叶子铺满小路。','The maple shed its leaves / in October / covering the path.','shed.s1 指自然脱落叶片、皮肤或毛发。','枫树秋季落叶。'),C('shed.s2','流出；摆脱','The cyclist shed water from her jacket at the doorway and then shed the heavy outer layer.','骑车人在门口抖掉夹克上的水，然后脱下厚外套。','The cyclist shed water / from her jacket / then shed the heavy layer.','shed.s2 可指流出液体或摆脱、去掉某物。','她抖掉水并脱下外套。'),C('shed.s3','棚；小屋；库房','Dad stores the lawn mower and garden tools in a small shed behind the house.','爸爸把割草机和园艺工具存放在房子后面的小棚屋里。','Dad stores the mower and tools / in a small shed / behind the house.','shed.s3 指用于存放物品或安置动物的简易建筑。','棚屋用来存放工具。')],M('The maple shed its leaves by growing every leaf permanently and never dropping any in autumn.','The maple shed its leaves by dropping them in autumn.','秋天落叶正是 shed leaves 的意思；永不落叶与之相反。','meaning'),[q('When did the maple shed its leaves?','in October','in the middle of spring','during a summer snowstorm','枫树在十月落叶。',1,'context'),q('What did the cyclist shed at the doorway?','water from her jacket and a heavy outer layer','a maple tree','a garden tool shed','骑车人在门口抖掉水并脱下厚外套。',2,'context'),q('Where were the lawn mower and tools stored?','in a small shed behind the house','inside the cyclist’s jacket','in a shareholder report','工具存放在房子后面的小棚屋里。',3,'context'),q('What does shed mean in “shed its leaves”?','lose something naturally','build a storage hut','share an object with others','shed its leaves 指树木自然落叶。',1,'meaning')]);
P('sheep','Sheep comes from Old English scēap; it names a woolly farm animal and, informally, a person who follows others without thinking.',[C('sheep.s1','羊；绵羊','The sheep grazed on the hillside while the farmer checked the flock’s water trough.','羊群在山坡上吃草，农夫则检查羊群的饮水槽。','The sheep grazed on the hillside / while the farmer / checked the water trough.','sheep.s1 指因羊毛和肉而饲养的厚毛家畜。','农夫为羊群检查饮水。'),C('sheep.s2','驯顺的人；盲从的人','The columnist warned readers not to act like sheep by repeating a rumor before checking the facts.','专栏作者提醒读者不要像盲从者一样，不查事实就重复谣言。','The columnist warned readers not to act like sheep / by repeating rumors / without checking facts.','sheep.s2 是非正式比喻，指不加思考地跟随他人的人。','文章批评未经核实便随声附和。')],M('The flock of sheep lived in the sea and hunted fish with sharp teeth.','The flock of sheep grazed on the hillside and drank from a trough.','羊是吃草的家畜，不是海中捕食者。','meaning'),[q('What did the sheep do on the hillside?','grazed','hunted fish','guarded a military gate','羊群在山坡上吃草。',1,'context'),q('What behavior did the columnist warn against?','repeating a rumor without checking facts','checking evidence before sharing news','providing water for a flock','专栏作者提醒读者不要未经核实就重复谣言。',2,'context'),q('What is a sheep in the farm example?','a woolly animal kept for wool and meat','a fish with sharp teeth','a company shareholder','农场句中的 sheep 指饲养以获取羊毛和肉的家畜。',1,'meaning'),q('What does “act like sheep” mean figuratively?','follow others without thinking','protect a herd from danger','share a water trough','比喻用法的 sheep 指盲目跟随他人。',2,'meaning')]);
P('sheepfold','Sheepfold combines sheep and fold (“enclosure”); it means a fenced area where sheep are gathered.',C('sheepfold.s1','羊圈','At dusk, the shepherd counted the lambs as they entered the sheepfold for the night.','黄昏时，牧羊人清点小羊，看着它们进入羊圈过夜。','The shepherd counted the lambs / as they entered the sheepfold / at dusk.','sheepfold.s1 指围起来供羊群聚集或过夜的地方。','围栏把羊群集中起来。'),M('The shepherd sent the sheep into the open field all night and called it a fenced sheepfold.','The shepherd gathered the sheep in a fenced sheepfold at night.','没有围栏的开阔田地不是羊圈。','meaning'),[q('When did the lambs enter the sheepfold?','at dusk','at midday during a snowstorm','before dawn the previous week','小羊在黄昏时进入羊圈。',1,'context'),q('What did the shepherd count?','the lambs','the company shares','the sheets on a bed','牧羊人清点了小羊。',1,'context'),q('What is a sheepfold?','a fenced area where sheep are gathered','a cloth made from sheep hide','a shelter for swimmers','sheepfold 指圈养或聚集羊群的围栏区域。',1,'meaning'),q('Which place is a sheepfold?','a fenced pen where a flock stays overnight','an unfenced hillside where sheep roam freely','a leather cover for a blade','夜间圈住羊群的围栏是 sheepfold。',1,'context')]);
P('sheepskin','Sheepskin combines sheep and skin; it means the hide of a sheep, used for clothing, rugs, or parchment.',C('sheepskin.s1','绵羊皮','The old sheepskin rug kept the stone floor warm beside the cabin’s fireplace.','旧羊皮地毯让小屋壁炉旁的石地板保持温暖。','The old sheepskin rug kept the floor warm / beside the cabin / fireplace.','sheepskin.s1 指可用于衣物、地毯或羊皮纸的绵羊皮。','羊皮制成地毯用于保暖。'),M('The rug was sheepskin even though it was woven from synthetic plastic and contained no animal hide.','The rug was made from sheepskin, the hide of a sheep.','没有羊皮的塑料地毯不属于 sheepskin。','meaning'),[q('Where was the sheepskin rug placed?','beside the cabin fireplace','inside the sheepfold gate','on the company’s meeting table','羊皮地毯铺在小屋壁炉旁。',1,'context'),q('What did it help keep warm?','the stone floor','a sharp knife','the riverbank','羊皮地毯让石地板保持温暖。',1,'context'),q('What is sheepskin?','the hide of a sheep','a woolly animal itself','a fenced area for sheep','sheepskin 指绵羊的皮。',1,'meaning'),q('Which product is sheepskin?','a rug made from a sheep’s hide','a rug made entirely of plastic','a metal sheet from a factory','用羊皮制成的地毯是 sheepskin。',1,'context')]);
P('sheer','Sheer comes from Old English scīr (“bright, clear”); it can mean complete or strong, very steep, or thin and nearly transparent.',[C('sheer.s1','纯粹的；完全的','The rescue team reached the village through sheer determination after the mountain road collapsed.','山路坍塌后，救援队凭着十足的决心抵达了村庄。','The rescue team arrived through sheer determination / after the mountain road / collapsed.','sheer.s1 用于强调程度完全或强烈。','强调抵达靠的是十足决心。'),C('sheer.s2','陡峭的；垂直的','The climbers stopped below a sheer cliff that rose almost vertically above the narrow trail.','登山者在一道近乎垂直耸立于狭窄山道上方的峭壁下停了下来。','The climbers stopped below a sheer cliff / that rose almost vertically / above the trail.','sheer.s2 指非常陡、近乎垂直的。','峭壁几乎垂直上升。'),C('sheer.s3','极薄的；透明的','Sunlight passed through the sheer curtain, leaving the room bright while still softening the view outside.','阳光透过薄纱窗帘照进来，房间明亮，而窗外景色仍变得柔和。','Sunlight passed through the sheer curtain / leaving the room bright / and softening the view.','sheer.s3 指织物极薄，几乎透明。','薄纱透光。')],M('The sheer cliff was a gentle slope that hikers could cross without climbing.','The sheer cliff rose steeply and almost vertically above the trail.','平缓山坡不是陡峭近乎垂直的峭壁。','meaning'),[q('What helped the rescue team reach the village?','sheer determination','a new road through the valley','a sheer curtain','救援队靠十足的决心抵达村庄。',1,'context'),q('How did the cliff rise above the trail?','almost vertically','as a gentle flat field','as a transparent sheet','峭壁近乎垂直耸立。',2,'context'),q('What did the sheer curtain do with sunlight?','let it pass through while softening the view','block all light completely','reflect it like a metal shield','薄纱窗帘让阳光透过并柔化景色。',3,'context'),q('What does sheer mean in “sheer determination”?','complete or intense','nearly transparent','very steep','sheer determination 指十足、强烈的决心。',1,'meaning')]);
P('sheet','Sheet comes from Old English scēte; it can mean bed linen, a flat piece of paper or material, or a wide moving mass of water, fire, or rain.',[C('sheet.s1','床单','Fresh sheets covered the guest bed before the family arrived for the weekend.','家人周末到来前，客房床上铺好了干净床单。','Fresh sheets covered the guest bed / before the family / arrived.','sheet.s1 指铺在床上的大块布料。','床单铺在客床上。'),C('sheet.s2','一张纸；薄片','The technician placed a sheet of glass over the display to protect it from scratches.','技术员在显示屏上放了一片玻璃，以防刮伤。','The technician placed a sheet of glass / over the display / to prevent scratches.','sheet.s2 指平整的一张纸、玻璃或金属薄片。','玻璃片保护显示屏。'),C('sheet.s3','一大片','A sheet of rain swept across the harbor, hiding the boats from view for several minutes.','一大片雨幕横扫港口，几分钟内遮住了船只。','A sheet of rain swept across the harbor / hiding the boats / for several minutes.','sheet.s3 指成片移动的水、火或雨。','雨幕遮住船只。')],M('A sheet of rain crossed the harbor as a single dry paper page remained untouched in the office.','A wide sheet of rain swept across the harbor and hid the boats.','这里的 sheet 指大片雨幕，不是未动的纸张。','meaning'),[q('What covered the guest bed?','fresh sheets','glass fragments','a sheepfold gate','客房床上铺着干净床单。',1,'context'),q('What did the technician place over the display?','a sheet of glass','a wool shawl','a rain barrel','技术员在显示屏上放了一片玻璃。',2,'context'),q('What hid the harbor boats?','a sheet of rain','a clean bed sheet','a sheet of paper','一大片雨幕遮住了港口的船只。',3,'context'),q('What does sheet mean in “a sheet of glass”?','a flat piece of glass','bed linen','a moving mass of rain','a sheet of glass 指一片平板玻璃。',2,'meaning')]);
P('sheets','Sheets is the plural of sheet; it can mean the pieces of cloth used on a bed or flat, thin pieces of paper, glass, or ice.',[C('sheets.s1','床单（复数）','The hotel changed the sheets after each guest checked out and before the next one arrived.','每位客人退房后、下一位到来前，酒店都会更换床单。','The hotel changed the sheets / after each guest checked out / before the next arrived.','sheets.s1 指铺在床上、供人睡卧的布片。','酒店更换客床床单。'),C('sheets.s2','一张张的片状物','The lake’s thin sheets of ice cracked as the morning sun warmed the surface.','晨光使湖面升温时，湖上一片片薄冰裂开了。','Thin sheets of ice cracked / as the morning sun / warmed the lake.','sheets.s2 指纸、玻璃或冰等材料的一张张薄片。','湖冰成片开裂。')],M('The hotel changed the sheets by replacing the mattress with a single sheet of glass.','The hotel changed the bed linens with fresh sheets.','玻璃板不是供人睡卧的床单。','meaning'),[q('When did the hotel change the sheets?','after each guest checked out','only when the lake froze','before the hotel was built','酒店在每位客人退房后更换床单。',1,'context'),q('What cracked on the lake?','thin sheets of ice','the hotel’s glass windows','a paper application','湖上一片片薄冰裂开了。',2,'context'),q('What are sheets in the hotel example?','pieces of cloth used to cover a bed','flat sheets of ice','paper used for a report','酒店句中的 sheets 指床单。',1,'meaning'),q('What does sheets mean in “sheets of ice”?','flat thin layers of ice','bed linens','large moving masses of rain','sheets of ice 指一片片薄冰。',2,'meaning')]);
P('shelf','Shelf comes from Old English scylfe; it can mean a flat board for storage or the underwater edge of a continent.',[C('shelf.s1','架子；搁板','She placed the heavy reference books on the lowest shelf so children could reach them safely.','她把厚重的参考书放在最下面的搁板上，方便孩子安全取阅。','She placed reference books / on the lowest shelf / within children’s reach.','shelf.s1 指墙上或柜子里用来放东西的平板。','搁板用于放置参考书。'),C('shelf.s2','大陆架','The survey ship mapped the continental shelf before measuring the deep ocean trench beyond it.','调查船先绘制大陆架地图，然后测量其外侧的深海海沟。','The ship mapped the continental shelf / before measuring / the deeper trench.','shelf.s2 指大陆边缘延伸到海下的区域。','海图将大陆架与深海沟区分。')],M('The reference books were placed on the lowest shelf by floating in the ocean beside a continental edge.','The books were placed on the lowest board inside the bookcase.','书架里的搁板不是海底大陆架。','meaning'),[q('Where did she put the heavy reference books?','on the lowest shelf','on the roof of the bookcase','on the ocean floor','她把参考书放在最下面的搁板上。',1,'context'),q('What did the survey ship map?','the continental shelf','the hotel bed sheets','the mountain cliff','调查船绘制了大陆架地图。',2,'context'),q('What is a shelf in the bookcase example?','a flat board for storing items','the underwater edge of a continent','a large cloth for a bed','bookcase 例句中的 shelf 指搁板。',1,'meaning'),q('What does continental shelf mean?','the submerged edge of a continent','a board attached to a wall','a fenced enclosure for sheep','continental shelf 指大陆边缘位于海下的区域。',2,'meaning')]);
P('shell','Shell comes from Old English scell, “hard covering”; it can mean an outer covering, an artillery projectile/casing, firing projectiles, or removing a shell.',[C('shell.s1','壳；贝壳；外壳','The turtle pulled its head inside its shell when the dog ran across the beach.','狗跑过海滩时，海龟把头缩进了壳里。','The turtle pulled its head / inside its shell / when the dog ran by.','shell.s1 指蛋、坚果、种子或海洋动物的坚硬外层。','海龟缩进硬壳内。'),C('shell.s2','炮弹；弹壳','A metal shell casing was found near the abandoned artillery position.','废弃炮位附近发现了一个金属炮弹壳。','A metal shell casing was found / near the abandoned / artillery position.','shell.s2 指由大型火炮发射的炮弹或其金属外壳。','炮位旁发现弹壳。'),C('shell.s3','炮击；剥去壳','The army shelled the empty fort, while cooks shelled peas for the evening meal.','军队炮击了空堡垒，而厨师们则为晚餐剥豌豆荚。','The army shelled the fort / while cooks shelled peas / for the meal.','shell.s3 作动词可指炮击地点，也可指剥去外壳。','同一动词可指炮击或剥壳。')],M('The turtle protected itself by leaving its hard shell behind and standing exposed on the beach.','The turtle withdrew its head into its hard shell for protection.','把硬壳丢下会失去保护，不符合例句。','meaning'),[q('What did the turtle pull inside its shell?','its head','a metal casing','a pea pod','海龟把头缩进壳里。',1,'context'),q('Where was the metal shell casing found?','near the abandoned artillery position','inside the turtle’s shell','on the hotel bed','金属弹壳在废弃炮位附近发现。',2,'context'),q('What did the cooks do to the peas?','removed their outer shells','fired them from a cannon','placed them on a bookshelf','厨师剥去了豌豆荚外壳。',3,'context'),q('What does shell mean in “the army shelled the fort”?','fired artillery projectiles at it','removed the fort’s outer coating by hand','protected a turtle','这里 shelled 指炮击堡垒。',2,'meaning')]);
P('shellfish','Shellfish combines shell and fish; it names aquatic animals with shells, including crabs, oysters, shrimp, and mussels.',C('shellfish.s1','贝类；有壳水生动物','The menu lists shellfish such as oysters and mussels, so diners with allergies can choose another dish.','菜单列出牡蛎和贻贝等贝类，因此过敏的食客可以选择其他菜肴。','The menu lists shellfish / such as oysters and mussels / for allergy information.','shellfish.s1 指有壳的水生动物，如蟹、牡蛎、虾和贻贝。','菜单标明贝类以提醒过敏顾客。'),M('Oysters and mussels are not shellfish because they live in water and have hard shells.','Oysters and mussels are shellfish because they are aquatic animals with shells.','牡蛎和贻贝正是有壳水生动物。','meaning'),[q('Which shellfish were named on the menu?','oysters and mussels','sheep and lambs','sharks and whales','菜单列出了牡蛎和贻贝。',1,'context'),q('Why might diners choose another dish?','because of shellfish allergies','because the oysters are semiarid','because the dish is a sentence','有贝类过敏的食客可以另选菜肴。',1,'context'),q('What is shellfish?','aquatic animals with shells','all fish regardless of shell','animals that live only on land','shellfish 指有壳的水生动物。',1,'meaning'),q('Which animal is shellfish?','a mussel','a sheep','a turtle with no aquatic habitat','贻贝属于 shellfish。',1,'context')]);
P('shelter','Shelter is recorded in Middle English; its earlier formation is uncertain. It means protection from danger/weather, a protective building, or the act of protecting/staying safe.',[C('shelter.s1','庇护；遮蔽；掩蔽','The hikers found shelter from the freezing rain beneath a broad rock ledge.','徒步者在宽阔的岩壁下躲避冰冷的雨。','The hikers found shelter / from freezing rain / beneath a rock ledge.','shelter.s1 指免受恶劣天气或危险的保护。','岩壁挡住冻雨。'),C('shelter.s2','避难所；收容所','The town opened a shelter where families could sleep safely after the apartment fire.','公寓失火后，镇上开放了一处避难所，让家庭能够安全过夜。','The town opened a shelter / where families could sleep / after the fire.','shelter.s2 指保护人或动物的建筑物。','家庭在避难所过夜。'),C('shelter.s3','保护；躲避','Volunteers sheltered the injured dog in a quiet room until the veterinarian arrived.','兽医到来前，志愿者把受伤的狗安置在安静房间里保护起来。','Volunteers sheltered the dog / in a quiet room / until the veterinarian arrived.','shelter.s3 作动词，指保护某人或待在安全处。','志愿者保护受伤的狗。')],M('The hikers found shelter from the freezing rain by standing in the open with no cover.','The hikers found shelter beneath a rock ledge that blocked the rain.','无遮蔽的空地无法提供庇护。','meaning'),[q('Where did the hikers shelter from the rain?','beneath a broad rock ledge','inside the burning apartment','on the exposed cliff edge','徒步者在宽阔岩壁下躲雨。',1,'context'),q('Why did the town open a shelter?','families needed a safe place after the fire','the apartment needed a new roof','the hikers wanted to sell the rock ledge','公寓失火后，家庭需要安全过夜的地方。',2,'context'),q('What did volunteers do for the injured dog?','protected it in a quiet room','sent it into the freezing rain','removed its shell','志愿者把受伤的狗安置在安静房间里保护起来。',3,'context'),q('What does shelter mean as a noun in “find shelter”?','protection from bad weather or danger','a metal projectile fired by artillery','a salary paid to a shepherd','find shelter 指找到遮蔽或保护。',1,'meaning')]);
P('sheltered','Sheltered is the past participle of shelter and an adjective; it can mean protected from harsh weather or having little experience of difficulty or the wider world.',[C('sheltered.s1','有遮蔽的；避风的','The sheltered cove stayed calm even when strong winds battered the open coast.','即使强风猛烈吹打开阔海岸，这处避风海湾仍很平静。','The sheltered cove stayed calm / while strong winds / battered the open coast.','sheltered.s1 指受保护、避开风雨等恶劣天气的。','海湾受地形遮挡。'),C('sheltered.s2','与世隔绝的；少经风雨的','Having grown up in a sheltered household, Mina was surprised by how difficult it was to find an apartment alone.','米娜在受保护的家庭环境中长大，因此独自找公寓时才发现事情如此困难。','Mina grew up in a sheltered household / and was surprised / by the difficulty of renting alone.','sheltered.s2 指缺乏困难经历或对外部世界经验较少的。','她过去很少独自处理现实难题。')],M('The sheltered cove was directly exposed to strong winds and had no protection from the open coast.','The sheltered cove was protected from the strongest winds.','无遮蔽、直面强风的海湾不是 sheltered。','meaning'),[q('What protected the cove from strong winds?','its sheltered position','a thin bedsheet','a sheepfold fence','海湾受地形遮挡，避开了强风。',1,'context'),q('Why was Mina surprised by renting alone?','she had grown up with little experience handling such difficulties','she had managed many apartments by herself for years','the cove was sheltered from the wind','米娜过去缺少独自处理这类困难的经验。',2,'context'),q('What does sheltered mean about the cove?','protected from harsh weather','exposed to every wind','crowded with apartments','cove 句中的 sheltered 指受保护、避风的。',1,'meaning'),q('What does sheltered mean about Mina’s upbringing?','she had little experience of difficulty or the wider world','she lived in a windy coastal cove','she worked as a shepherd','描述米娜成长环境时，sheltered 指少经风雨、经验有限。',2,'meaning')]);
P('shelve','Shelve is formed from shelf; it means put objects on shelves or postpone/drop a plan by figuratively putting it aside.',[C('shelve.s1','把……放到架上','Please shelve the returned novels by author name so readers can find them quickly.','请按作者姓名把归还的小说放上书架，方便读者快速找到。','Please shelve the returned novels / by author name / so readers can find them.','shelve.s1 指把物品放到架子上或排列在架上。','书按作者姓名上架。'),C('shelve.s2','搁置；暂缓','The council shelved the bridge project until engineers could produce a safer design.','工程师提出更安全的设计前，市议会暂缓了桥梁项目。','The council shelved the bridge project / until engineers / produced a safer design.','shelve.s2 比喻把计划暂时放到一边，即延期或搁置。','项目因等待安全方案而推迟。')],M('The council shelved the bridge project by starting construction before the engineers finished the safer design.','The council shelved the project until engineers produced a safer design.','立即开工不是暂缓项目。','meaning'),[q('How should the returned novels be shelved?','by author name','by the color of the room','inside a sheepfold','小说按作者姓名上架。',1,'context'),q('Why did the council shelve the bridge project?','engineers needed to produce a safer design','the bridge was already open and safe','the novels needed a new shelf','市议会等工程师提出更安全设计后再推进项目。',2,'context'),q('What does shelve mean in the library example?','put books onto shelves','cancel a meeting at nine sharp','cut wool from a sheep','图书馆句中的 shelve 指把书放到架上。',1,'meaning'),q('What does shelve mean in the council example?','postpone or set a project aside','build a shelf for the project','finish construction immediately','市议会句中的 shelve 指暂缓项目。',2,'meaning')]);
P('shepherd','Shepherd comes from Old English sceaphierde (“sheep-herder”); it can mean a person who tends sheep or guide people like a shepherd guides a flock.',[C('shepherd.s1','牧羊人','The shepherd led the flock across the valley and checked the lambs before closing the gate.','牧羊人带羊群穿过山谷，并在关门前检查小羊。','The shepherd led the flock / across the valley / and checked the lambs.','shepherd.s1 指以照料羊群为工作的人。','牧羊人照看羊群和小羊。'),C('shepherd.s2','带领；护送；指导','Two volunteers shepherded visitors through the crowded gallery toward the emergency exit.','两名志愿者引导参观者穿过拥挤的展厅前往紧急出口。','Volunteers shepherded visitors / through the crowded gallery / toward the exit.','shepherd.s2 作动词，指像牧羊人带领羊群一样引导人群。','志愿者带人离开拥挤展厅。')],M('The shepherd abandoned the flock outside the gate and refused to check whether the lambs were safe.','The shepherd led the flock across the valley and checked the lambs.','不照看也不带领羊群，与牧羊人的职责相反。','meaning'),[q('Where did the shepherd lead the flock?','across the valley','through the crowded gallery','into the parliament','牧羊人带羊群穿过山谷。',1,'context'),q('Where did the volunteers shepherd visitors?','toward the emergency exit','into the sheepfold','onto the open coast','志愿者引导参观者前往紧急出口。',2,'context'),q('What is a shepherd?','a person whose work is caring for sheep','a person who owns company shares','a soldier who guards a gate','shepherd 名词指照料羊群的人。',1,'meaning'),q('What does shepherd mean as a verb here?','guide people through a place','sell them a bridge project','sharpen their tools','shepherd 作动词指引导人群通过某地。',2,'meaning')]);
P('shield','Shield comes from Old English scield; it can mean a protective plate, a person or thing that blocks danger/blame, or the act of protecting.',[C('shield.s1','盾；挡牌','The guard raised a wooden shield to stop stones from striking the doorway.','守卫举起木盾，挡住飞向门口的石块。','The guard raised a wooden shield / to stop stones / from striking the doorway.','shield.s1 指用来阻挡打击、石块或射击的硬质防护板。','木盾挡住投来的石块。'),C('shield.s2','防护物；屏障；保护人','A row of trees formed a shield against the cold wind for the outdoor seating area.','一排树木为户外座位区挡住了冷风。','A row of trees formed a shield / against the cold wind / for the seating area.','shield.s2 指防止危险、责备或恶劣天气影响的屏障或保护者。','树木形成防风屏障。'),C('shield.s3','保护；掩护；庇护','The supervisor shielded the trainee from unfair blame by explaining that the faulty machine had caused the error.','主管说明错误是机器故障造成的，从而保护实习生免受不公正责备。','The supervisor shielded the trainee / from unfair blame / by explaining the machine fault.','shield.s3 作动词指保护某人或某物免受伤害、攻击或批评。','主管说明事实以免实习生背锅。')],M('The supervisor shielded the trainee from blame by falsely accusing the trainee in front of the whole team.','The supervisor shielded the trainee from blame by explaining the machine fault.','公开诬陷实习生没有保护其免受责备。','meaning'),[q('What did the wooden shield stop?','stones striking the doorway','cold wind reaching outdoor tables','the sheep leaving the fold','木盾挡住飞向门口的石块。',1,'context'),q('What formed a shield against the cold wind?','a row of trees','a sheet of rain','a broken shell','一排树木为座位区挡风。',2,'context'),q('How did the supervisor shield the trainee?','explained that the faulty machine caused the error','blamed the trainee without checking','sent the trainee away','主管说明机器故障造成错误，保护实习生免受不公责备。',3,'context'),q('What does shield mean as a noun in the guard example?','a hard plate that stops blows or stones','a person who owns a company share','a leather wrap for a wool shawl','守卫句中的 shield 指挡住打击的硬质防护板。',1,'meaning')]);
P('shift','Shift comes from Old English sciftan (“arrange, divide”); it can mean move position, change an opinion or focus, a work period, or a change of gear/place/emphasis.',[C('shift.s1','移动；挪动','Could you shift the chair a little closer to the window so the walkway stays clear?','你能把椅子往窗边挪一点吗？这样走道就能保持畅通。','Could you shift the chair / closer to the window / so the walkway stays clear?','shift.s1 指把某物或自己从一个位置移到另一个位置。','椅子被挪到窗边。'),C('shift.s2','转变；改变看法或重点','After reviewing the new evidence, the committee shifted its focus from cost to safety.','审查新证据后，委员会把重点从成本转向安全。','The committee shifted its focus / from cost / to safety after reviewing evidence.','shift.s2 指改变观点、处境或主要关注点。','委员会改变了讨论重点。'),C('shift.s3','轮班；班次','Marta works the night shift at the hospital and leaves just after sunrise.','玛尔塔在医院上夜班，日出后不久下班。','Marta works the night shift / at the hospital / and leaves after sunrise.','shift.s3 指轮流工作的一个固定时段。','她在医院上夜班。'),C('shift.s4','变换；换挡；转移','The driver shifted into first gear before climbing the steep hill.','司机在爬陡坡前换入一挡。','The driver shifted into first gear / before climbing / the steep hill.','shift.s4 指换挡或位置、强调点等发生变化。','司机改变了汽车挡位。')],M('The driver shifted into first gear by leaving the car in the same gear throughout the climb.','The driver shifted into first gear before climbing the hill.','不改变挡位与 shift into first gear 相反。','meaning'),[q('Where should the chair be shifted?','closer to the window','into the sheepfold','away from the clear walkway','椅子要往窗边挪动。',1,'context'),q('What did the committee shift its focus to?','safety','the color of the chair','the night schedule','委员会把重点转向安全。',2,'context'),q('When does Marta work?','the night shift','the morning shearing season','the annual shareholder report','玛尔塔在医院上夜班。',3,'context'),q('What gear did the driver shift into?','first gear','reverse only','the highest gear before the hill','司机爬坡前换入一挡。',4,'context')]);
P('shifting','Shifting is formed from shift and -ing; as an adjective it describes something moving or changing so often that it is hard to rely on.',C('shifting.s1','不停变动的','The hikers struggled to cross the shifting sand because each step changed the ground beneath their feet.','徒步者难以穿过流动的沙地，因为每一步都会改变脚下的地面。','The hikers struggled on shifting sand / because each step / changed the ground.','shifting.s1 指不断移动或变化、难以依靠的。','沙地在脚下持续移动。'),M('The hikers crossed shifting sand easily because the ground stayed completely fixed beneath every step.','The hikers struggled because the sand moved beneath their feet.','地面完全不动与 shifting sand 相反。','meaning'),[q('What made crossing the sand difficult?','the ground changed beneath each step','the ground was a fixed stone path','the hikers had no shoes','流动的沙地在每一步下都会改变。',1,'context'),q('What kind of surface did they cross?','shifting sand','a sturdy wooden shelf','a calm paved road','徒步者穿过的是不断移动的沙地。',1,'context'),q('What does shifting mean here?','moving or changing continually','permanently fixed in one position','covered with a hard outer shell','shifting 指持续移动或变化。',1,'meaning'),q('Which conditions are shifting?','sand dunes that move as the wind blows','a concrete floor that never moves','a sealed room with no change','被风吹动、持续移动的沙丘是 shifting。',1,'context')]);
P('shilling','Shilling comes from Old English scilling; in pre-decimal British currency it was a coin worth one-twentieth of a pound.',C('shilling.s1','旧币制中的一先令','Before decimalization, a British shopkeeper could price a small item at two shillings and sixpence.','英国货币十进制化之前，店主可以把一件小商品标价为两先令六便士。','Before decimalization, an item cost two shillings / and sixpence / in Britain.','shilling.s1 指英国旧币制中等于二十分之一英镑的硬币。','例句使用十进制化之前的英国币值。'),M('In pre-decimal Britain, one shilling was worth twenty pounds.','In pre-decimal Britain, one shilling was worth one-twentieth of a pound.','一先令是二十分之一英镑，不是二十英镑。','meaning'),[q('What price could the shopkeeper set?','two shillings and sixpence','two pounds and six shillings','six pounds and twenty pence','店主可把商品标价为两先令六便士。',1,'context'),q('When was the shilling used?','before British decimalization','in every modern currency today','only during the Roman Empire','shilling 是英国货币十进制化前的币种。',1,'context'),q('How much was one old British shilling?','one-twentieth of a pound','twenty pounds','one hundredth of a penny','一先令等于二十分之一英镑。',1,'meaning'),q('Which statement about the old shilling is correct?','it was a pre-decimal British coin','it was a modern paper banknote worth twenty pounds','it was a type of sheepfold','shilling 是英国十进制化前使用的硬币。',1,'meaning')]);
P('shimmer','Shimmer is from Old English scimerian (“shine faintly”); it can mean shine with soft, changing light or the soft light itself.',[C('shimmer.s1','闪烁；发微光','Heat made the distant road shimmer above the fields in the afternoon sun.','午后阳光下，热气使远处的道路在田野上方微微闪动。','The distant road shimmered / above the fields / in the afternoon sun.','shimmer.s1 作动词，指发出柔和、似在变化的光。','热气和阳光使远路微微闪动。'),C('shimmer.s2','微光；闪光','A silver shimmer on the lake reflected the last light of sunset.','湖面上的银色微光映出日落前最后一缕光。','A silver shimmer on the lake / reflected / the last sunset light.','shimmer.s2 作名词，指轻微变化的柔和光线或其效果。','湖面泛起银色微光。')],M('The road shimmered in the afternoon sun by remaining completely dark and showing no light or movement.','The road shimmered as heat and sunlight made it seem to waver.','完全黑暗且无光波动不是 shimmer。','meaning'),[q('What shimmered above the fields?','the distant road','the moonless night sky','the leather knife sheath','远处的道路在阳光下微微闪动。',1,'context'),q('What did the silver shimmer on the lake reflect?','the last light of sunset','the midday rainstorm','the garden tools','湖面微光映出日落前最后的光线。',2,'context'),q('What does shimmer mean as a verb?','shine with soft, changing light','become completely dark','break into sharp pieces','shimmer 作动词指发出柔和变动的微光。',1,'meaning'),q('What does shimmer mean as a noun?','a soft light that moves slightly','a fixed metal shield','a work period at a hospital','shimmer 作名词指轻微变化的柔和光线。',2,'meaning')]);
P('shin','Shin (the leg noun) comes from Old English scinu; the verb meaning climb by gripping is of uncertain origin and is a separate sense.',[C('shin.s1','胫；小腿前侧','The runner felt a dull ache along his shin after striking it against the low bench.','跑步者的小腿前侧撞到矮凳后感到隐隐作痛。','The runner felt an ache / along his shin / after striking the bench.','shin.s1 指膝盖与脚踝之间腿部的前侧。','撞击造成胫部疼痛。'),C('shin.s2','攀；爬','The child shinned up the low tree by gripping the trunk with both arms and legs.','孩子用双臂和双腿抱紧树干，爬上了那棵矮树。','The child shinned up the tree / by gripping its trunk / with arms and legs.','shin.s2 作动词，指用手臂和腿抓住物体向上或向下攀爬。','孩子抱住树干往上爬。')],M('The child shinned up the tree by walking away from it without touching the trunk.','The child shinned up the tree by gripping the trunk with arms and legs.','不接触树干就无法以抓握方式攀爬。','meaning'),[q('Where did the runner feel an ache?','along the front of his lower leg','in his shoulder','inside the tree trunk','跑步者的小腿前侧感到疼痛。',1,'context'),q('How did the child climb the tree?','gripped the trunk with arms and legs','used a ladder while keeping away from the trunk','rolled beneath the tree','孩子抱住树干用四肢往上爬。',2,'context'),q('What is the shin?','the front part of the leg between knee and ankle','the back of the shoulder','a protective cover for a blade','shin 指膝盖与脚踝之间腿部的前侧。',1,'meaning'),q('What does shin mean as a verb?','climb by gripping with arms and legs','cut wool from a sheep','shift a chair across a room','shin 作动词指用四肢抓握攀爬。',2,'meaning')]);
P('shine','Shine comes from Old English scīnan; it can mean emit or direct light, perform exceptionally, brightness/polish, or polish a surface.',[C('shine.s1','发光；照耀；反射光','The lighthouse shines across the bay so fishing boats can find the harbor entrance at night.','灯塔的光照过海湾，使渔船夜间能够找到港口入口。','The lighthouse shines across the bay / so boats can find / the harbor entrance.','shine.s1 指发出光或把光照到表面上。','灯塔发光帮助船只导航。'),C('shine.s2','出众；表现出色','During the interview, Asha shone when she explained how she had solved the difficult design problem.','面试中，阿莎讲解自己如何解决复杂设计问题时表现出色。','Asha shone during the interview / when she explained / her solution.','shine.s2 比喻表现出色到引人注意。','她在面试中展示了能力。'),C('shine.s3','光亮；光泽','The shine on the polished table reflected the window clearly.','抛光桌面的光泽清楚地映出了窗户。','The shine on the polished table / reflected / the window clearly.','shine.s3 作名词指明亮或平滑抛光后的光泽。','桌面光泽映出窗户。'),C('shine.s4','擦亮；使光亮','Before the parade, the cadet shined his boots until the leather looked bright.','游行前，学员把皮靴擦得锃亮。','The cadet shined his boots / until the leather / looked bright.','shine.s4 作及物动词，指擦拭表面使其发亮。','擦靴子使皮面变亮。')],M('The lighthouse shines across the bay by staying dark and giving no light to boats.','The lighthouse shines across the bay to guide boats toward the harbor.','灯塔发光引导船只，不会保持黑暗。','meaning'),[q('What does the lighthouse help fishing boats find?','the harbor entrance','the sheepfold','the interview room','灯塔帮助渔船找到港口入口。',1,'context'),q('When did Asha shine in the interview?','when she explained her solution to a difficult design problem','when she forgot every question','when she polished a table','阿莎讲解设计问题的解决方案时表现出色。',2,'context'),q('What reflected the window clearly?','the shine on the polished table','the lighthouse’s shadow','a sheep’s wool','抛光桌面的光泽映出窗户。',3,'context'),q('What did the cadet do to his boots?','polished them until the leather looked bright','put them inside a sword sheath','cut them with shears','学员把皮靴擦亮了。',4,'context')]);
P('shingle','Shingle has roofing and shore-pebble senses with partly distinct histories; it means a tapered roof board or a mass of small pebbles on a shore.',C('shingle.s1','屋顶板；海滩卵石','Workers replaced the cracked shingles on the cottage roof while waves rolled rounded shingle across the nearby beach.','工人更换了小屋屋顶上开裂的屋面板，而海浪把圆卵石滚到附近海滩。','Workers replaced roof shingles / while waves rolled shore shingle / onto the beach.','shingle.s1 指斜边屋面板，也可指海岸上的卵石层。','同一词条列有屋顶板和海滩卵石两个用法。'),M('The roof was covered with shingle, meaning a single sheet of glass stretched across it.','The roof was covered with tapered roofing shingles.','屋面 shingle 是屋面板，不是整张玻璃。','meaning'),[q('What did the workers replace on the cottage?','cracked roof shingles','the roof’s glass windows','the shoreline pebbles','工人更换了小屋屋顶上开裂的屋面板。',1,'context'),q('What did waves roll onto the beach?','rounded shingle pebbles','roofing boards','sheets of paper','海浪把圆卵石滚到海滩。',1,'context'),q('What can shingle mean on a roof?','a tapered roofing board','a large boat','a bed linen','屋顶上的 shingle 指斜边屋面板。',1,'meaning'),q('What can shingle mean on a shore?','a mass of small pebbles','a protective sword cover','a group of sheep','海岸上的 shingle 指一层小卵石。',1,'meaning')]);
P('shining','Shining is the present participle/adjective of shine; it can mean giving off a steady bright glow or, figuratively, excellent and worth copying.',[C('shining.s1','发光的；闪耀的','A shining lantern hung outside the cabin and lit the path through the dark garden.','一盏明亮的灯笼挂在小屋外，照亮了穿过黑暗花园的小路。','A shining lantern hung outside / and lit / the dark garden path.','shining.s1 指稳定发光、明亮闪耀的。','灯笼发光照亮小路。'),C('shining.s2','杰出的；卓越的','The mentor described her careful field notes as a shining example of honest research.','导师称赞她细致的田野笔记是诚实研究的杰出范例。','Her field notes were a shining example / of careful and honest / research.','shining.s2 比喻非常优秀、成功或值得效仿的。','笔记被视为优秀范例。')],M('The shining lantern gave off no light and remained completely dark in the garden.','The shining lantern glowed and lit the garden path.','完全不发光的灯笼不是 shining。','meaning'),[q('What did the shining lantern light?','the path through the dark garden','the ocean trench','the inside of a closed sheepfold','灯笼照亮了黑暗花园的小路。',1,'context'),q('What were the mentor’s shining example?','the student’s careful, honest field notes','a broken ship’s mast','a cheap roof repair','导师把田野笔记称为杰出范例。',2,'context'),q('What does shining mean about the lantern?','giving off a steady bright glow','being completely dark','having a thin transparent fabric','灯笼句中的 shining 指明亮发光的。',1,'meaning'),q('What does shining mean in “a shining example”?','excellent and worth copying','wet and slippery','only reflecting light physically','shining example 指杰出、值得效仿的范例。',2,'meaning')]);
P('shiny','Shiny is formed from shine and -y; it describes a surface that looks bright because it reflects light.',C('shiny.s1','发光的；有光泽的','The mechanic polished the bicycle bell until its shiny surface reflected the workshop lamp.','技工把自行车铃擦亮，直到它的光泽表面映出车间灯光。','The mechanic polished the bell / until its shiny surface / reflected the lamp.','shiny.s1 指表面反射光、看上去明亮有光泽的。','抛光后铃面能反光。'),M('The bell had a shiny surface even though it was matte black and reflected no light.','The bell looked shiny after its surface was polished to reflect the lamp.','不反光的哑光表面没有 shiny 的光泽。','meaning'),[q('What reflected the workshop lamp?','the polished bicycle bell','the sheepfold gate','the shattered glass','自行车铃的光泽表面映出了车间灯光。',1,'context'),q('What did the mechanic do to the bell?','polished it','sent it abroad','covered it with a wool shawl','技工把铃擦亮了。',1,'context'),q('What does shiny describe?','a bright surface that reflects light','a surface that absorbs all light','a sound that is harshly critical','shiny 描述能反光、看上去有光泽的表面。',1,'meaning'),q('Which object is shiny?','a polished bell reflecting a lamp','a matte panel with no reflection','a dark cloth in a closed box','能映出灯光的抛光铃面是 shiny。',1,'context')]);
P('ship','Ship comes from Old English scip; it can mean a large sea-going vessel, transport goods, or the people who work aboard a vessel as a group.',[C('ship.s1','大船；舰','The ship carried passengers across the rough sea and reached the island before dawn.','这艘船载着乘客穿过汹涌海面，在黎明前抵达岛屿。','The ship carried passengers / across the rough sea / before dawn.','ship.s1 指在海上运送货物、乘客或用于作战的大型船只。','大型船只横渡海面。'),C('ship.s2','运送；装运；发货','The supplier will ship the replacement pump by air so the hospital receives it tomorrow.','供应商将空运替换水泵，以便医院明天收到。','The supplier will ship the pump / by air / so it arrives tomorrow.','ship.s2 作动词，指通过海运、陆运或空运把商品寄出。','商品通过空运发货。'),C('ship.s3','船员；船上的人（集合）','The ship waited in port while its ship prepared for the overnight voyage.','船员准备夜间航行时，这艘船仍停在港口。','The ship waited in port / while its ship prepared / for the voyage.','ship.s3 可集合地指在船上工作的全体人员。','此处第二个 ship 指船员集体。')],M('The supplier shipped the pump to the hospital by keeping it in the warehouse and never sending it.','The supplier shipped the pump by sending it to the hospital.','不发货而留在仓库，不符合 ship 的运送义。','meaning'),[q('What did the ship carry across the sea?','passengers','roof shingles','a night shift','这艘船载着乘客穿过汹涌海面。',1,'context'),q('How will the supplier ship the replacement pump?','by air','by leaving it in the warehouse','by sea on a sheepfold','供应商将空运替换水泵。',2,'context'),q('What does ship mean in “the ship prepared for the voyage”?','the people who work aboard a vessel','a cargo vessel itself','a batch of goods sent to a customer','这里的 ship 指船员集体。',3,'meaning'),q('What does ship mean as a verb?','send goods to a customer by a transport route','repair a vessel at a shipyard','use a sharp blade to cut wool','ship 作动词指把商品运送给顾客。',2,'meaning')]);
P('shipbuilding','Shipbuilding combines ship and building; it means the industry and craft of constructing ships.',C('shipbuilding.s1','造船；造船业','Shipbuilding expanded along the bay after the new dry dock opened for large steel vessels.','新干船坞为大型钢船开放后，海湾沿岸的造船业扩大了。','Shipbuilding expanded along the bay / after the dry dock / opened for large vessels.','shipbuilding.s1 指建造船只的行业和工艺。','干船坞启用后造船活动增加。'),M('Shipbuilding at the dry dock consisted only of planting trees and never constructing or repairing vessels.','Shipbuilding at the dry dock involved constructing large vessels.','不建造船只的工作不属于造船业。','meaning'),[q('What opened along the bay?','a new dry dock for large vessels','a sheepfold for lambs','a shared laundry room','大型船只新干船坞在海湾沿岸开放。',1,'context'),q('What happened to the local industry afterward?','shipbuilding expanded','the sea dried up','the shipyard became a hotel','新船坞开放后，当地造船业扩大。',1,'context'),q('What does shipbuilding mean?','the industry and craft of constructing ships','the business of sending parcels by air','the crew working aboard a vessel','shipbuilding 指建造船舶的行业和工艺。',1,'meaning'),q('Which job belongs to shipbuilding?','constructing a steel vessel in a dry dock','selling a wool shawl at a store','checking a sharpener in a classroom','在干船坞建造钢船属于 shipbuilding。',1,'context')]);
P('shipload','Shipload combines ship and load; it means the quantity of goods or people that fills or is carried by one ship.',C('shipload.s1','一整船的量','A shipload of grain arrived at the harbor after weeks at sea.','一整船谷物经过数周航行后抵达港口。','A shipload of grain arrived / at the harbor / after weeks at sea.','shipload.s1 指一艘船装载的货物或人员数量。','谷物按整船运抵。'),M('The shipload of grain filled a single paper envelope and never went aboard any vessel.','The shipload of grain filled a ship arriving at the harbor.','一封信的容量不能构成整船货物。','meaning'),[q('What arrived at the harbor?','a shipload of grain','a single sheet of paper','a shipment of one pencil','一整船谷物抵达港口。',1,'context'),q('How long had the grain been at sea?','for weeks','for a few seconds','it never traveled','谷物经过数周航行抵达。',1,'context'),q('What is a shipload?','the quantity carried by one ship','the crew of a vessel','a tool for building a ship','shipload 指一艘船装载的数量。',1,'meaning'),q('Which amount is a shipload?','all the cargo carried by one vessel','one item in a shop window','one worker’s night shift','一艘船所载的全部货物可称为 shipload。',1,'context')]);
P('shipment','Shipment is formed from ship and -ment; it can mean the act of transporting goods or a quantity of goods sent together.',[C('shipment.s1','装运；运送','The shipment of medical supplies left the warehouse by truck just after sunrise.','医疗用品在日出后不久从仓库用卡车发出。','The shipment left the warehouse / by truck / just after sunrise.','shipment.s1 指把货物从一处运送到另一处的过程。','医疗用品通过卡车运送。'),C('shipment.s2','一批货；一批装运物','The first shipment contained 400 replacement filters packed in twenty boxes.','第一批货物有400个替换滤芯，装在二十个箱子里。','The first shipment contained 400 filters / packed / in twenty boxes.','shipment.s2 指同一时间发出的一批货物。','货物作为一批一同发送。')],M('The shipment of filters was sent in one batch, but the boxes were left at the warehouse and never transported.','The shipment of filters was transported from the warehouse to its destination.','货物未离开仓库就没有完成运送过程。','meaning'),[q('How did the medical supplies leave the warehouse?','by truck','by a sheepfold','by a paper sheet','医疗用品用卡车从仓库运出。',1,'context'),q('How many filters were in the first shipment?','400','40','4,000','第一批货物包含400个替换滤芯。',2,'context'),q('What does shipment mean in the sunrise example?','the act of transporting goods','a ship’s crew','a building where ships are constructed','第一句 shipment 指货物的运输过程。',1,'meaning'),q('What does shipment mean in “the first shipment contained 400 filters”?','a quantity of goods sent together','the act of polishing a bell','a single captain on a vessel','此处 shipment 指一批一起发出的货物。',2,'meaning')]);
P('shipping','Shipping is formed from ship and -ing; it can mean the business of transporting cargo or a country’s/company’s vessels considered as a group.',[C('shipping.s1','航运业；海运','Shipping costs rose after storms closed the main port and forced cargo onto longer routes.','风暴关闭主要港口、迫使货物改走更长路线后，航运成本上升了。','Shipping costs rose / after storms closed the main port / and rerouted cargo.','shipping.s1 指通过海路或其他路线运送货物的业务。','港口关闭使运输成本上涨。'),C('shipping.s2','船舶；商船队','The nation’s shipping gathered in the southern harbor before beginning a joint training exercise.','该国的船队在开始联合训练前集结于南部港口。','The nation’s shipping gathered / in the southern harbor / for training.','shipping.s2 总称一个国家或公司的船舶。','该国多艘船舶集结。')],M('Shipping costs fell because the port closed and every cargo route became longer and more difficult.','Shipping costs rose when the closed port forced cargo onto longer routes.','更长路线导致成本上升，不是下降。','meaning'),[q('Why did shipping costs rise?','the main port closed and cargo had to take longer routes','ships used the shortest route in calm weather','a shipload of grain arrived early','港口关闭迫使货物改走更长路线，运输成本因此上升。',1,'context'),q('Where did the nation’s shipping gather?','in the southern harbor','inside a dry dock’s office','at the shop counter','该国船队集结在南部港口。',2,'context'),q('What does shipping mean in “shipping costs”?','the business of transporting cargo','the nation’s fleet of vessels','a piece of cloth worn over the shoulders','shipping costs 中 shipping 指货物运输业务。',1,'meaning'),q('What does “the nation’s shipping” mean?','its ships considered as a group','the price of transporting a parcel','its harbor construction workers','the nation’s shipping 指该国的船舶总称。',2,'meaning')]);
P('shipwreck','Shipwreck combines ship and wreck; it means an accident that destroys or strands a ship, or the wreck that remains.',C('shipwreck.s1','船只失事；沉船','The divers mapped the shipwreck on the seabed and recovered several pieces of its broken mast.','潜水员绘制了海底沉船的地图，并打捞起几块断裂的桅杆。','The divers mapped the shipwreck / on the seabed / and recovered mast pieces.','shipwreck.s1 指摧毁或搁浅船只的事故，也指事故留下的残骸。','潜水员调查沉船残骸。'),M('The shipwreck was a newly built vessel sailing safely at sea with no accident or damage.','The shipwreck was the remains of a vessel destroyed at sea.','安全航行且没有损伤的船不是沉船。','meaning'),[q('Where did divers map the shipwreck?','on the seabed','inside a sheepfold','on a shop shelf','潜水员在海底绘制沉船地图。',1,'context'),q('What did they recover?','pieces of the broken mast','a clean bed sheet','a sharpener','潜水员打捞起几块断裂桅杆。',1,'context'),q('What can shipwreck mean?','a ship-destroying accident or the remains left behind','a shipyard where boats are built','the crew on a ship','shipwreck 可指船只失事或留下的残骸。',1,'meaning'),q('Which discovery is a shipwreck?','the remains of a vessel that was destroyed at sea','a new ship leaving the harbor safely','a carpenter building a boat','海上失事船只留下的残骸是 shipwreck。',1,'context')]);
P('shipwright','Shipwright combines ship and wright (“maker, worker”); it means a skilled craft worker who builds or repairs wooden ships.',C('shipwright.s1','造船匠','The shipwright replaced the damaged oak ribs of the wooden fishing boat before it returned to the water.','木船重新下水前，造船匠更换了受损的橡木肋骨。','The shipwright replaced oak ribs / in the wooden fishing boat / before relaunch.','shipwright.s1 指建造或修理木船的熟练工匠。','工匠修复船体结构。'),M('The shipwright repaired the fishing boat by replacing its engine with a wool shawl and never working on the hull.','The shipwright repaired the wooden vessel by replacing its damaged ribs.','造船匠修船体，不会以披肩代替发动机。','meaning'),[q('What did the shipwright replace?','damaged oak ribs','the harbor’s road signs','the boat’s crew','造船匠更换了船上的橡木肋骨。',1,'context'),q('What kind of vessel was repaired?','a wooden fishing boat','a stone bridge','a glass lantern','工匠修理的是一艘木制渔船。',1,'context'),q('What is a shipwright?','a skilled worker who builds or repairs wooden ships','a person who sells tickets for a voyage','a sailor who guards a sheepfold','shipwright 指建造或修理木船的熟练工匠。',1,'meaning'),q('Which person is a shipwright?','a craft worker fitting new ribs into a wooden hull','a harbor clerk shipping a parcel','a diver mapping an old wreck','为木船船体安装新肋骨的工匠是 shipwright。',1,'context')]);
P('shipyard','Shipyard combines ship and yard; it means a waterside works where ships are built or repaired.',C('shipyard.s1','造船厂；修船厂','The tug entered the shipyard for a hull inspection and replacement of two corroded plates.','拖船进入修船厂检查船体，并更换两块腐蚀的钢板。','The tug entered the shipyard / for a hull inspection / and plate replacement.','shipyard.s1 指建造或修理船舶的水边场地和工厂。','船厂检查并维修船体。'),M('The tug entered the shipyard to buy groceries, while no ships were ever built or repaired there.','The tug entered the shipyard for inspection and hull repairs.','只卖杂货、不建修船舶的地方不是船厂。','meaning'),[q('What did the tug need at the shipyard?','a hull inspection and two replacement plates','a wool sheepskin and a shawl','a night shift and a hotel bed','拖船需要检查船体并更换钢板。',1,'context'),q('Where was the shipyard located by definition?','beside the water','on a mountain summit','inside a shopping centre','shipyard 是水边建造或修理船舶的场地。',1,'context'),q('What is a shipyard?','a works where ships are built or repaired','the crew of a vessel','the act of sending goods by truck','shipyard 指建造或修理船舶的船厂。',1,'meaning'),q('Which place is a shipyard?','a waterside facility repairing a tug’s hull','a shop selling only wool clothes','an office that processes shareholders','修理拖船船体的水边设施是 shipyard。',1,'context')]);
P('shirk','Shirk is recorded in English from the 17th century; its earlier origin is uncertain. It means avoid a job or duty one is expected to do.',C('shirk.s1','逃避；推卸','Maya did not shirk her duty: she stayed after the storm to help clear the blocked school entrance.','玛雅没有逃避责任：暴风雨后，她留下来帮忙清理被堵住的校门。','Maya did not shirk her duty / and stayed after the storm / to clear the entrance.','shirk.s1 指逃避本应承担的工作或职责。','她留下来履行职责。'),M('Maya shirked her duty by staying late and clearing the blocked entrance as promised.','Maya shirked her duty by leaving without helping clear the entrance.','留下并完成任务不是逃避责任。','meaning'),[q('What did Maya help clear?','the blocked school entrance','a ship’s hull','a shelf of shirts','玛雅帮助清理被堵住的校门。',1,'context'),q('When did she stay to help?','after the storm','before the school was built','during the shipwreck','玛雅在暴风雨后留下来帮忙。',1,'context'),q('What does shirk mean?','avoid a duty one is expected to do','take responsibility for completing a task','protect someone from danger','shirk 指逃避本应承担的职责。',1,'meaning'),q('Who shirked a duty?','a worker who leaves instead of doing an assigned cleanup','a volunteer who stays to finish the cleanup','a supervisor who assigns a fair task','离开而不做被分派清理工作的员工是在 shirk。',1,'context')]);
P('shirt','Shirt comes from Old English scyrte; it means a light upper-body garment with sleeves and a collar, or in compounds a casual or sports top.',[C('shirt.s1','衬衫；衬衣','He tucked his clean shirt into his trousers before the formal job interview.','正式求职面试前，他把干净衬衫塞进裤子里。','He tucked his clean shirt / into his trousers / before the interview.','shirt.s1 指通常带袖子和衣领、覆盖上身的轻便衣物。','衬衫适合正式面试。'),C('shirt.s2','运动衫；休闲上衣（复合词中）','The club’s home shirt is bright yellow, while its away shirt is dark blue.','俱乐部主场球衣是亮黄色，客场球衣则是深蓝色。','The club’s home shirt is yellow / while its away shirt / is dark blue.','shirt.s2 可在复合词中指运动或休闲上衣。','home shirt 和 away shirt 指球衣。')],M('He wore a shirt to the interview by leaving his upper body uncovered and putting the garment on his legs.','He wore a collared shirt on his upper body to the interview.','衬衫穿在上身，不会套在腿上。','meaning'),[q('What did he tuck into his trousers?','his clean shirt','his home shirt from the club','a bed sheet','他把干净衬衫塞进裤子里。',1,'context'),q('What color was the club’s home shirt?','bright yellow','dark blue','white and green','俱乐部主场球衣是亮黄色。',2,'context'),q('What is a shirt in the interview example?','a light upper-body garment with sleeves and a collar','a sheet of glass','a ship’s protective shell','面试句中的 shirt 指带袖和衣领的上身衣物。',1,'meaning'),q('What does “away shirt” refer to?','a sports or leisure top worn by a team','a formal business suit','a wool rug made from a sheep hide','away shirt 指球队穿的运动上衣。',2,'meaning')]);
P('shit','Shit is an Old English word for bodily waste and is now highly vulgar; it can also be a rude term for trouble/nonsense or an exclamation of anger or surprise.',[C('shit.s1','粪便（粗俗语）','The vet found dog shit on the path and asked the owner to clean it up.','兽医在小路上发现狗粪，便请主人清理。','The vet found dog shit / on the path / and asked for cleanup.','shit.s1 是表示粪便的粗俗词，应注意语体。','例句说明其字面意义和粗俗语体。'),C('shit.s2','倒霉事；胡说八道（粗俗）','“I don’t believe that shit,” the mechanic said when the seller claimed the damaged engine was new.','卖家声称损坏的发动机是新的时，技工说：“我才不信那套鬼话。”','The mechanic said “I don’t believe that shit” / about the seller’s / false claim.','shit.s2 是粗俗说法，可指胡说、麻烦或毫无价值的东西。','技工不信卖家的说辞。'),C('shit.s3','咒骂；表示恼怒或惊讶（粗俗）','“Shit!” Noor shouted when she realized she had left the keys inside the locked car.','诺尔发现钥匙落在锁着的车里时，喊了一声“糟了！”','“Shit!” Noor shouted / when she saw the keys / inside the locked car.','shit.s3 是粗俗的感叹词，可表达恼怒、疼痛或惊讶。','感叹词表达突然懊恼。')],M('At a formal meeting, the chair used shit repeatedly in every sentence to maintain a polite professional register.','At a formal meeting, the chair used a polite word such as “nonsense” instead of shit.','shit 是粗俗词，不适合正式场合的礼貌语体。','meaning'),[q('What did the vet find on the path?','dog shit','a sharp shard','a shipload of grain','兽医在小路上发现了狗粪。',1,'context'),q('What claim did the mechanic reject?','that a damaged engine was new','that the path needed cleaning','that a ship was at the harbor','技工不信卖家声称损坏发动机是新的。',2,'context'),q('Why did Noor shout “Shit!”?','she had left the keys inside the locked car','the car’s keys were in her hand','she was welcoming a visitor','诺尔发现钥匙落在锁着的车里，因此惊呼。',3,'context'),q('What register does shit have?','highly vulgar and unsuitable for formal polite speech','formal and appropriate in every meeting','technical and neutral','shit 属于粗俗语，不适合正式礼貌场合。',1,'meaning')]);
P('shiver','Shiver is recorded in Old and Middle English for trembling; it can mean an involuntary shake from cold, fear, or illness, or one brief episode of it.',[C('shiver.s1','颤抖；哆嗦','The soaked hiker began to shiver in the cold wind while waiting for the rescue vehicle.','淋湿的徒步者在冷风中等待救援车辆时开始发抖。','The soaked hiker began to shiver / in the cold wind / while waiting for rescue.','shiver.s1 作动词，指因寒冷、恐惧或疾病而不受控制地轻微颤抖。','冷风使湿衣徒步者发抖。'),C('shiver.s2','一阵颤抖；寒战','A shiver ran through Leila when the distant metal gate slammed in the empty yard.','空荡的院子里远处金属门砰然关上时，莱拉打了个寒战。','A shiver ran through Leila / when the metal gate / slammed in the empty yard.','shiver.s2 作名词，指短暂的一阵颤抖。','突然巨响引起一阵寒战。')],M('The soaked hiker shivered in the cold wind while remaining perfectly still and warm.','The soaked hiker shivered because the cold wind made the body tremble.','完全温暖且不动与因寒冷发抖相矛盾。','meaning'),[q('Why did the hiker shiver?','the cold wind and soaked clothes made the hiker tremble','the rescue vehicle arrived in warm sunshine','the gate was polished','湿衣徒步者在冷风中发抖。',1,'context'),q('What caused Leila’s shiver?','a metal gate slammed in the empty yard','a soft lamp glowed steadily','a shirt was folded','远处金属门砰然关上使莱拉打了个寒战。',2,'context'),q('What does shiver mean as a verb?','shake involuntarily from cold, fear, or illness','shine with a steady glow','put a blade into its sheath','shiver 作动词指因冷、怕或病而不由自主地颤抖。',1,'meaning'),q('What is a shiver as a noun?','one brief episode of trembling','a ship’s entire cargo','a formal upper-body garment','名词 shiver 指一阵短暂的颤抖。',2,'meaning')]);
P('shoal','Shoal has Old English roots for shallow water and a separate fish-group sense; it can mean a school of fish or a shallow place in a river or sea.',[C('shoal.s1','鱼群','A shoal of silver fish turned together beneath the pier when the shadow of a boat passed overhead.','一艘船的影子掠过时，码头下的一群银色鱼同时转向。','A shoal of fish turned together / beneath the pier / as a boat passed.','shoal.s1 指朝同一方向一起游动的大群鱼。','鱼群在船影经过时一起转向。'),C('shoal.s2','浅滩；浅水处','The ferry slowed near a shoal where rocks lay just below the surface of the channel.','渡船在浅滩附近减速，那里岩石就在水道表面下方。','The ferry slowed near a shoal / where rocks lay / below the water surface.','shoal.s2 指河流或海中沙石接近水面的浅水区。','浅滩上的岩石影响通航。')],M('The ferry sped through the shoal because the rocks were far beneath the deepest part of the channel.','The ferry slowed near the shoal because rocks lay just below the surface.','浅滩水浅、岩石近水面，船只应减速。','meaning'),[q('How did the fish move beneath the pier?','they turned together','they scattered onto the road','they stayed inside the shipyard','一群银鱼同时转向。',1,'context'),q('Why did the ferry slow down?','rocks lay just below the surface at the shoal','the water was too deep to sail','a fish had become a shipwreck','浅滩岩石靠近水面，渡船因此减速。',2,'context'),q('What is a shoal in the fish example?','a large group of fish swimming together','a single fish near the pier','a vessel’s cargo','鱼的例句中 shoal 指鱼群。',1,'meaning'),q('What is a shoal in the ferry example?','a shallow area where sand or rock lies near the surface','a deep trench beyond a continental shelf','a group of swimmers in a pool','渡船句中的 shoal 指有浅水和近水底岩石的浅滩。',2,'meaning')]);
P('shock','Shock comes through French choc from a word for a collision or blow; it can mean strong upset, a dangerous circulatory state, electric pain, or cause surprise/anger.',[C('shock.s1','震惊；打击','The sudden closure of the clinic came as a shock to families who depended on its evening service.','诊所突然关闭让依赖其夜间服务的家庭感到震惊。','The clinic closure came as a shock / to families / who relied on evening care.','shock.s1 指突然强烈的惊讶、恐惧或难过感。','关闭消息令人震惊。'),C('shock.s2','休克','After the serious injury, the paramedic watched for signs of shock, including pale skin and a weak pulse.','严重受伤后，急救员观察是否出现休克迹象，包括皮肤苍白和脉搏微弱。','The paramedic watched for shock / after the injury / checking skin and pulse.','shock.s2 指严重受伤或突发疾病后血液循环不足的危险状态。','急救员留意休克体征。'),C('shock.s3','电击；触电','A small shock from the faulty plug made Ravi pull his hand away from the outlet.','故障插头造成轻微电击，拉维立刻把手从插座旁缩回。','A small shock from the faulty plug / made Ravi / pull his hand away.','shock.s3 指电流通过身体时产生的突然疼痛。','插头漏电让他触电。'),C('shock.s4','使震惊；使气愤','The court ruling shocked residents who had expected the historic park to remain public.','法院裁决让原本以为历史公园会继续开放的居民感到震惊。','The court ruling shocked residents / who expected / the park to remain public.','shock.s4 作动词指使人突然惊讶、害怕或愤怒。','裁决出乎居民预料。')],M('The court ruling shocked residents by confirming exactly the outcome they had confidently expected.','The court ruling shocked residents because it contradicted what they expected.','完全符合预期通常不会使人突然震惊。','meaning'),[q('Why did the clinic closure come as a shock?','families depended on its evening service','the clinic had never provided any service','the families had already closed it','依赖夜间服务的家庭对诊所关闭感到震惊。',1,'context'),q('What signs of shock did the paramedic check?','pale skin and a weak pulse','shiny shoes and a bright shirt','a high score and a low shelf','急救员查看皮肤苍白和脉搏微弱等休克迹象。',2,'context'),q('What caused Ravi’s electric shock?','a faulty plug','a cold wind','a court ruling','故障插头使拉维触电。',3,'context'),q('What did the court ruling do to residents?','surprised or upset them suddenly','protected them from cold weather','shipped goods to them','裁决使居民突然感到震惊。',4,'meaning')]);
P('shocked','Shocked is the past participle of shock; as an adjective it means extremely surprised and upset by something unexpected.',C('shocked.s1','感到震撼的','The passengers were shocked when the captain announced that the ship had lost power near the reef.','船长宣布船只在礁石附近失去动力时，乘客们震惊不已。','The passengers were shocked / when the captain announced / the loss of power.','shocked.s1 指因意外之事而极度惊讶和难过。','船只失去动力的消息出乎乘客意料。'),M('The passengers were shocked by the expected announcement and had known the ship would lose power all week.','The passengers were shocked because the ship’s loss of power was unexpected.','早已知道的事情不会造成同样的意外震惊。','meaning'),[q('What news shocked the passengers?','the ship had lost power near the reef','the ship had arrived safely in port','the crew had polished the deck','乘客得知船在礁石附近失去动力后震惊不已。',1,'context'),q('Who made the announcement?','the captain','the shipwright','the hotel clerk','船长宣布了船只失去动力的消息。',1,'context'),q('What does shocked mean?','extremely surprised and upset by something unexpected','calm because nothing changed','angry at a routine schedule','shocked 指因意外之事而极度惊讶和难过。',1,'meaning'),q('Which passenger is shocked?','one who suddenly learns the ship has lost power','one who knew for days that the ship would stop','one who quietly reads a timetable','突然得知船只失去动力的乘客感到 shocked。',1,'context')]);
P('shocking','Shocking is formed from shock and -ing; it can mean so bad, rude, or unacceptable that it upsets people, or very great/severe in amount.',[C('shocking.s1','令人震惊的；骇人的','The inspection found shocking neglect: the emergency doors were chained shut and the alarms did not work.','检查发现了骇人的疏忽：紧急出口被链条锁住，警报器也无法工作。','The inspection found shocking neglect / with chained emergency doors / and failed alarms.','shocking.s1 指糟糕、粗鲁或不可接受到令人震惊的。','安全隐患令人震惊。'),C('shocking.s2','极大的；过分的','The family received a shocking electricity bill after a faulty heater ran continuously for a month.','故障加热器连续运行一个月后，一家人收到了一张金额高得惊人的电费单。','The family received a shocking bill / after the heater / ran for a month.','shocking.s2 可强调数量或金额极大、严重。','账单金额异常高。')],M('The inspection found shocking neglect because all emergency doors worked perfectly and every alarm passed its test.','The inspection found shocking neglect because emergency doors were chained shut and alarms failed.','安全设备全部完好与严重疏忽相反。','meaning'),[q('What was wrong with the emergency doors?','they were chained shut','they opened automatically','they were replaced with new alarms','紧急出口被链条锁住。',1,'context'),q('Why was the electricity bill shocking?','a faulty heater ran continuously for a month','the family used no electricity','the bill was only one penny','故障加热器运行一个月导致电费高得惊人。',2,'context'),q('What does shocking mean in the inspection example?','so bad or unacceptable that it upsets people','very ordinary and harmless','a mild change in temperature','检查句中的 shocking 指糟糕到令人震惊。',1,'meaning'),q('What does shocking mean about the bill?','extremely large or severe in amount','surprisingly small and low','a dangerous state after an injury','电费句中的 shocking 强调金额高得惊人。',2,'meaning')]);
P('shoddy','Shoddy first described inferior cloth made from reclaimed wool and now means badly made from cheap material or done carelessly/dishonestly.',[C('shoddy.s1','劣质的；粗制滥造的','The shoddy raincoat split at the seams after one short walk in light rain.','这件劣质雨衣在小雨中走了一小段路后就从接缝处裂开。','The shoddy raincoat split / at the seams / after one short walk.','shoddy.s1 指用廉价材料粗制、容易损坏的。','雨衣很快开线。'),C('shoddy.s2','卑劣的；不诚实的','The inspector condemned the contractor’s shoddy work because he hid unsafe wiring behind fresh paint.','检查员谴责承包商卑劣的做法，因为他用新油漆遮住了不安全的线路。','The inspector condemned shoddy work / because unsafe wiring / was hidden behind paint.','shoddy.s2 指做事不认真或不诚实、缺乏尊重的。','承包商掩盖危险线路。')],M('The contractor’s work was shoddy even though he carefully exposed every unsafe wire and repaired it correctly.','The contractor’s work was shoddy because he hid unsafe wiring behind paint.','公开并妥善修复危险线路不是卑劣或粗心的做法。','meaning'),[q('What happened to the raincoat?','its seams split after a short walk','it remained intact through years of storms','it became a sheet of glass','劣质雨衣走了一小段路后接缝就裂开了。',1,'context'),q('What did the contractor hide?','unsafe wiring behind fresh paint','a shipwreck in the harbor','a sheep in a fold','承包商用新油漆遮住了不安全线路。',2,'context'),q('What does shoddy mean about the raincoat?','badly made from cheap material','excellent and worth copying','extremely bright and reflective','雨衣句中的 shoddy 指劣质、粗制滥造。',1,'meaning'),q('What does shoddy mean about the contractor’s work?','careless or dishonest and disrespectful','polished and carefully checked','a very large quantity','承包商句中的 shoddy 指不认真或不诚实。',2,'meaning')]);
P('shoe','Shoe comes from Old English scōh; it can mean footwear covering the foot or the metal fitting placed on a horse’s hoof.',[C('shoe.s1','鞋','Rafi left his muddy shoes by the door before entering the clean kitchen.','拉菲进干净的厨房前把沾泥的鞋留在门边。','Rafi left his muddy shoes / by the door / before entering.','shoe.s1 指通常有坚实鞋底、用于户外保护脚部的鞋。','泥鞋留在门外。'),C('shoe.s2','给马钉蹄铁','The farrier will shoe the mare with new metal plates before the long trail ride.','长途骑行前，蹄铁匠会给母马钉上新的金属蹄铁。','The farrier will shoe the mare / with new metal plates / before the trail ride.','shoe.s2 作动词，指给马蹄装上金属蹄铁。','蹄铁匠给马钉蹄铁。')],M('Rafi left his muddy shoes on his feet before stepping onto the clean kitchen counter.','Rafi removed his muddy shoes by the door before entering the kitchen.','把脏鞋穿进干净空间与例句动作相反。','meaning'),[q('Where did Rafi leave his muddy shoes?','by the door','on the kitchen table','inside the mare’s hoof','拉菲把沾泥的鞋留在门边。',1,'context'),q('What will the farrier do to the mare?','fit new metal plates to its hooves','remove its shoes and leave it barefoot','give it a wool shawl','蹄铁匠要给母马钉上新的金属蹄铁。',2,'context'),q('What is a shoe in the first example?','footwear with a firm sole','a metal plate fixed to a horse’s hoof','a tool for polishing a bicycle bell','第一句 shoe 指穿在脚上的鞋。',1,'meaning'),q('What does shoe mean as a verb?','fit a horse with a metal shoe','put a person’s foot into footwear','repair a wooden vessel','shoe 作动词指给马钉蹄铁。',2,'meaning')]);
P('shoelace','Shoelace combines shoe and lace; it means a lace threaded through a shoe to tie it closed.',C('shoelace.s1','系鞋的带子','One shoelace came untied during the race, so I stopped before it caught beneath my shoe.','比赛中一根鞋带松开了，我停下来把它系好，以免被踩到。','One shoelace came untied / during the race / so I stopped to tie it.','shoelace.s1 指穿过鞋眼、用来系紧鞋子的带子。','鞋带松开后需要重新系紧。'),M('She tied the shoelace around her wrist to close the shoe without threading it through the eyelets.','She threaded the shoelace through the eyelets and tied the shoe closed.','系鞋带需要穿过鞋眼并绑紧，而不是绑在手腕上。','meaning'),[q('What happened during the race?','one shoelace came untied','the shoe grew a new shoot','the shorebird flew away','比赛中一根鞋带松开了。',1,'context'),q('Why did the runner stop?','to keep the loose lace from catching under the shoe','to polish a horse’s hoof','to shop for a new shirt','跑者停下是为了防止松开的鞋带被踩住。',1,'context'),q('What is a shoelace?','a lace used to tie a shoe closed','a metal plate fitted to a horse','a tool for repairing ships','shoelace 指用来系紧鞋子的带子。',1,'meaning'),q('Which item is a shoelace?','a cord threaded through shoe eyelets','a rubber sole fixed beneath a shoe','a strap worn around the shoulders','穿过鞋眼的绳带是 shoelace。',1,'context')]);
P('shoemaker','Shoemaker combines shoe and maker; it means a person whose work is making or repairing shoes.',C('shoemaker.s1','制鞋匠','The shoemaker replaced the worn soles on two pairs of boots and stitched the leather by hand.','制鞋匠给两双靴子换了磨损的鞋底，并用手缝好皮革。','The shoemaker replaced worn soles / and stitched / the leather by hand.','shoemaker.s1 指以制作或修理鞋子为工作的人。','工匠更换鞋底并缝皮革。'),M('The shoemaker repaired the boots by refusing to touch them and sending the owner to a shipyard.','The shoemaker repaired the boots by replacing their worn soles.','拒绝修理并转送他处，不是制鞋匠的工作。','meaning'),[q('What did the shoemaker replace?','the worn soles on two pairs of boots','the harbor’s shoreline','a ship’s wooden ribs','制鞋匠更换了两双靴子的磨损鞋底。',1,'context'),q('How did the shoemaker stitch the leather?','by hand','with a ship’s anchor','with a sheet of glass','工匠用手缝制皮革。',1,'context'),q('What is a shoemaker?','a person who makes or repairs shoes','a person who fits metal shoes to horses only','a worker who constructs sea-going ships','shoemaker 指制作或修理鞋子的人。',1,'meaning'),q('Which worker is a shoemaker?','a craftsperson replacing boot soles','a shipwright repairing a wooden hull','a shop assistant selling sheets','更换靴子鞋底的工匠是 shoemaker。',1,'context')]);
P('shoemaking','Shoemaking combines shoe and making; it means the work or business of producing shoes.',C('shoemaking.s1','制鞋业','The town’s shoemaking workshop trains apprentices to cut leather, shape lasts, and stitch uppers.','镇上的制鞋作坊培训学徒裁皮、制作鞋楦并缝合鞋面。','The shoemaking workshop trains apprentices / to cut leather / and stitch uppers.','shoemaking.s1 指生产鞋子的工作或行业。','作坊教授制鞋工艺。'),M('The town’s shoemaking workshop trained apprentices to build ships but never made any footwear.','The town’s shoemaking workshop trained apprentices to produce shoes.','造船而不制鞋不是 shoemaking。','meaning'),[q('What does the workshop teach apprentices to cut?','leather','shoreline stones','a horse’s metal shoe','学徒学习裁切皮革。',1,'context'),q('What else do apprentices learn to stitch?','shoe uppers','a ship’s sail only','a sheepfold gate','学徒还学习缝合鞋面。',1,'context'),q('What does shoemaking mean?','the work or business of producing shoes','the act of buying shoes in a store','the activity of fitting horses with horseshoes only','shoemaking 指制作鞋子的工作或行业。',1,'meaning'),q('Which activity is shoemaking?','cutting leather and stitching shoe uppers','shopping for ready-made boots','building a shipyard','裁皮并缝制鞋面属于 shoemaking。',1,'context')]);
P('shoeshine','Shoeshine combines shoe and shine; it can mean the act of polishing shoes or the gloss produced by polishing them.',C('shoeshine.s1','擦鞋；鞋面的光泽','The station offered a quick shoeshine, and the polished leather reflected the lights above the platform.','车站提供快速擦鞋服务，擦亮的皮革映出了站台上方的灯光。','The station offered a shoeshine / and the polished leather / reflected the lights.','shoeshine.s1 指擦亮鞋子的服务，也可指擦鞋后形成的光泽。','擦鞋服务让皮鞋有了光泽。'),M('The customer received a shoeshine when the worker covered the leather with mud and removed its gloss.','The customer received a shoeshine that polished the leather and restored its gloss.','抹泥去光泽与擦鞋服务相反。','meaning'),[q('Where was the shoeshine offered?','at the station','at the shipyard','inside the shorebird’s nest','车站提供擦鞋服务。',1,'context'),q('What reflected the platform lights?','the polished leather','a matte rubber sole','a sheet of rain','擦亮的皮革映出了灯光。',1,'context'),q('What can shoeshine mean?','the act of polishing shoes or the gloss it produces','a lace that ties the shoe','a person who makes shoes','shoeshine 可指擦鞋服务或擦亮后的光泽。',1,'meaning'),q('Which result is a shoeshine?','a polished gloss on leather shoes','mud covering the leather','a loose lace under a boot','皮鞋擦亮后形成的光泽是 shoeshine。',1,'context')]);
P('shoot','Shoot comes from Old English scēotan (“send forth, throw”); it can mean fire or send an object at a target, wound/kill with a gun, film, or a new plant growth/filming session.',[C('shoot.s1','开枪；射击；射门','During practice, Lena shot three arrows toward the foam target and checked where each one landed.','练习时，莉娜向泡沫靶射出三支箭，并查看每支箭落在哪里。','Lena shot three arrows / toward the foam target / and checked their landing points.','shoot.s1 指用枪、弓或球等快速向目标发射或投射。','弓箭朝练习靶射出。'),C('shoot.s2','射伤；射杀','The report said an illegal hunter had shot and wounded a deer; a ranger treated the animal at the wildlife center.','报告称一名非法猎人射伤了一只鹿；护林员在野生动物中心为它治疗。','An illegal hunter had shot a deer / and a ranger treated / its wound.','shoot.s2 指用枪击中并伤害或杀死某人或动物。','鹿被子弹射伤后接受治疗。'),C('shoot.s3','拍摄；摄影','The crew will shoot the final scene at the harbor before the light fades.','剧组将在天色变暗前于港口拍摄最后一场戏。','The crew will shoot the final scene / at the harbor / before the light fades.','shoot.s3 指拍摄照片或电影。','剧组拍摄电影场景。'),C('shoot.s4','嫩枝；芽；拍摄场次','A new green shoot appeared beside the old stump after the spring rain.','春雨后，老树桩旁冒出一根绿色新芽。','A new green shoot appeared / beside the old stump / after spring rain.','shoot.s4 可指植物新长出的嫩枝，也可指一次拍摄场次。','树桩旁萌发新枝。')],M('The crew shot the final scene by filming it after all the lights and cameras had been removed.','The crew shot the final scene while the cameras and lights were set up at the harbor.','没有摄影设备且没有拍摄，不能说拍摄了场景。','meaning'),[q('What did Lena shoot during practice?','three arrows toward the foam target','the deer with an illegal rifle','the harbor with a camera','莉娜向泡沫靶射出三支箭。',1,'context'),q('What happened to the deer in the report?','it was wounded by an illegal hunter and treated by a ranger','it was filmed at the harbor','it grew a new shoot after the rain','鹿被非法猎人射伤后由护林员治疗。',2,'context'),q('What will the film crew shoot at the harbor?','the final scene','a new green plant shoot','three arrows at a target','剧组将在港口拍摄最后一场戏。',3,'context'),q('What is the new green shoot beside the stump?','a new growth on a plant','a filmed scene','a bullet wound','树桩旁的绿色 shoot 指新长出的嫩枝。',4,'meaning')]);
P('shoot up','Shoot up combines shoot and up; it means rise very quickly to a high level or grow taller very quickly.',[C('shoot up.s1','（价格等）猛涨；飙升','Rent prices shot up after the new rail station opened and demand for nearby apartments increased.','新火车站开放、附近公寓需求增加后，租金猛涨。','Rent prices shot up / after the rail station opened / and demand increased.','shoot up.s1 指价格或数值快速升到高位。','车站开放后租金迅速上升。'),C('shoot up.s2','快速长高','The young willow shot up during the wet spring and soon reached the garden fence.','这棵小柳树在多雨的春天里迅速长高，很快就到了花园围栏的高度。','The young willow shot up / during the wet spring / reaching the fence.','shoot up.s2 指儿童或幼小动物快速长高。','柳树快速长到围栏高。')],M('The rent shot up after demand fell sharply and every nearby apartment became cheaper.','The rent shot up when demand increased after the station opened.','需求下降、房租变便宜与猛涨相反。','meaning'),[q('What caused nearby rents to shoot up?','the new rail station opened and demand increased','the station closed and apartments emptied','the willow tree was cut down','新车站开放、需求增加后租金猛涨。',1,'context'),q('How did the willow grow?','it quickly reached the garden fence','it shrank below the soil','it became a shipyard','柳树在多雨春季里迅速长到围栏高。',2,'context'),q('What does shoot up mean about rent?','rise very quickly to a high level','fall slowly to a low level','remain fixed for years','租金句中的 shoot up 指猛涨。',1,'meaning'),q('What does shoot up mean about the willow?','grow taller very quickly','be fired toward a target','lose its leaves naturally','柳树句中的 shoot up 指快速长高。',2,'meaning')]);
P('shop','Shop comes from Old English sceoppa (“booth, stall”); it can mean a place where goods are sold, go shopping, or a workshop where things are made or repaired.',[C('shop.s1','商店；店铺','The shop closes at six, so we bought the batteries before the evening train arrived.','商店六点关门，所以我们在晚班火车到达前买好了电池。','The shop closes at six / so we bought batteries / before the train arrived.','shop.s1 指向公众出售商品的建筑或房间。','顾客在商店购买电池。'),C('shop.s2','购物','I usually shop at the market on Saturday mornings for fruit and fresh bread.','我通常周六早上去市场买水果和新鲜面包。','I usually shop at the market / on Saturday mornings / for fruit and bread.','shop.s2 作动词指到商店购买东西。','去市场采购食品。'),C('shop.s3','车间；工场','The bicycle shop repaired frames in the back workshop while the front room served customers.','自行车店在后面的工场修理车架，前屋则接待顾客。','The bicycle shop repaired frames / in the back workshop / while the front served customers.','shop.s3 可指制造或修理物品的工作场所。','后屋用来修理自行车。')],M('We shopped for batteries at the store after it had closed for the night and locked its doors.','We bought batteries at the shop before it closed at six.','商店关门后顾客无法在那里购买电池。','meaning'),[q('When did the shop close?','at six','at midnight on Saturday','before it opened in the morning','商店六点关门。',1,'context'),q('What did the speaker shop for at the market?','fruit and fresh bread','a metal shipload','a new shoreline','说话者去市场买水果和新鲜面包。',2,'context'),q('What happened in the bicycle shop’s back room?','frames were repaired','batteries were sold to customers only','a shorebird nested','自行车车架在后面的工场修理。',3,'context'),q('What does shop mean as a verb?','go to shops and buy things','make or repair an object in a workshop','own company shares','shop 作动词指去商店购物。',2,'meaning')]);
P('shop assistant','Shop assistant combines shop and assistant; it means a person who works in a store and serves customers.',C('shop assistant.s1','店员；营业员','The shop assistant showed Farah three sizes of hiking boots and explained which sole had better grip.','店员给法拉看了三种尺码的登山靴，并说明哪种鞋底防滑性更好。','The shop assistant showed three boot sizes / and explained / which sole had better grip.','shop assistant.s1 指在商店工作、为顾客服务的人。','店员介绍商品并回答问题。'),M('The shop assistant served customers by refusing to answer questions or show any products.','The shop assistant helped Farah compare boot sizes and sole grip.','拒绝服务不是店员为顾客提供帮助。','meaning'),[q('What products did the shop assistant show Farah?','three sizes of hiking boots','three shiploads of grain','three sheets of glass','店员给法拉看了三种尺码的登山靴。',1,'context'),q('What feature did the assistant explain?','which sole had better grip','which shoreline was shortest','which shirt had a shilling price','店员说明了哪种鞋底防滑性更好。',1,'context'),q('What is a shop assistant?','a store worker who serves customers','a person who owns the store','a customer visiting several stores','shop assistant 指在商店为顾客服务的店员。',1,'meaning'),q('Who is a shop assistant?','someone who helps customers choose goods in a store','someone who buys goods only for personal use','someone who repairs ships at a shipyard','在商店帮助顾客挑选商品的人是 shop assistant。',1,'context')]);
P('shop price','Shop price combines shop and price; it means the retail amount customers pay for goods in a store.',C('shop price.s1','商店售价；零售价','The shop price includes the sales tax, so the customer pays the amount printed on the shelf label.','商店售价包含销售税，因此顾客支付货架标签上印出的金额。','The shop price includes sales tax / and matches / the shelf label.','shop price.s1 指顾客在商店购买商品时支付的价格。','标价已包含销售税。'),M('The shop price was the wholesale amount paid by the factory before the goods reached any store.','The shop price was the retail amount a customer paid in the store.','工厂的批发成本不是顾客在商店支付的零售价。','meaning'),[q('What did the shop price include?','sales tax','the cost of a shipwreck','a shoe’s shoeshine','货架上的商店售价已包含销售税。',1,'context'),q('Where was the price printed?','on the shelf label','on the shorebird’s wing','inside the ship’s hull','价格印在货架标签上。',1,'context'),q('What does shop price mean?','the retail amount a customer pays in a store','the factory’s wholesale cost before retail','the price of building a shop','shop price 指顾客在商店支付的零售价。',1,'meaning'),q('Which amount is the shop price?','the final retail amount on a store shelf label','the factory’s cost before shipping','the price a wholesaler pays to a supplier','商店货架上顾客实际支付的金额是 shop price。',1,'context')]);
P('shopkeeper','Shopkeeper combines shop and keeper; it means a person who owns or runs a small retail store.',C('shopkeeper.s1','店主；零售店老板','The shopkeeper locked the door after the last customer left and counted the day’s receipts.','最后一位顾客离开后，店主锁上门并清点当天的收款单。','The shopkeeper locked the door / after the last customer / and counted receipts.','shopkeeper.s1 指拥有或经营小型零售商店的人。','店主负责关门并核账。'),M('The shopkeeper was merely a shopper who visited once and had no role in running the store.','The shopkeeper ran the store and counted its receipts at closing.','偶尔来购物的顾客不是经营商店的人。','meaning'),[q('What did the shopkeeper do after the last customer left?','locked the door and counted receipts','repaired a ship’s mast','sheared a sheep','店主关门后清点当天收款单。',1,'context'),q('When did the shopkeeper lock the door?','after the last customer left','before the store opened to customers','during a shipwreck','最后一位顾客离开后店主锁门。',1,'context'),q('What is a shopkeeper?','a person who owns or runs a small shop','a person who only visits stores to buy goods','a person who works as a shipwright','shopkeeper 指拥有或经营小商店的人。',1,'meaning'),q('Which person is a shopkeeper?','the owner who opens and runs a neighborhood store','a customer buying one pair of shoes','a delivery driver shipping a parcel','开办并经营社区商店的人是 shopkeeper。',1,'context')]);
P('shopper','Shopper is formed from shop and -er; it means someone who visits stores to buy goods.',C('shopper.s1','购物的人','Each shopper received a reusable bag at the market entrance before choosing vegetables.','每位购物者在市场入口处领到一个可重复使用的袋子，然后挑选蔬菜。','Each shopper received a reusable bag / before choosing / vegetables at the market.','shopper.s1 指到商店或市场购买商品的人。','顾客领袋后挑选蔬菜。'),M('The shopper delivered vegetables to every market stall without buying or visiting any store.','The shopper visited the market to choose and buy vegetables.','送货商而非前往购买的人，不符合 shopper。','meaning'),[q('What did each shopper receive?','a reusable bag','a shopkeeper’s key','a shipwright’s tool','每位购物者领到一个可重复使用的袋子。',1,'context'),q('What did the shopper choose?','vegetables','shipbuilding materials','a shoreline map','购物者在市场挑选蔬菜。',1,'context'),q('What is a shopper?','someone who visits stores to buy goods','someone who owns a small store','someone who builds ships','shopper 指到商店购物的人。',1,'meaning'),q('Who is a shopper?','a person selecting groceries at a market','a shop owner counting receipts','a worker repairing a ship','在市场挑选食品的人是 shopper。',1,'context')]);
P('shopping','Shopping is formed from shop and -ing; it means the act of buying goods, especially as a household task.',C('shopping.s1','买东西','Their weekly shopping included bread, vegetables, soap, and food for the dog.','他们每周采购的东西包括面包、蔬菜、肥皂和狗粮。','Their weekly shopping included / bread, vegetables, soap / and dog food.','shopping.s1 指购买商品的活动，尤其是日常家庭采购。','采购清单列出日常用品。'),M('Their weekly shopping included only goods they refused to buy and left every shelf empty.','Their weekly shopping included the food and household items they purchased.','购物指购买物品，不是拒绝购买。','meaning'),[q('What did their weekly shopping include?','bread, vegetables, soap, and dog food','shipbuilding, shingling, and shearing','only a shoreline map','每周采购包括面包、蔬菜、肥皂和狗粮。',1,'context'),q('How often did they shop for these items?','weekly','once in a century','only after closing the store','他们每周采购这些物品。',1,'context'),q('What does shopping mean?','the act of purchasing goods','the work of making shoes','the owner of a small store','shopping 指购买商品的活动。',1,'meaning'),q('Which activity is shopping?','buying groceries and household supplies','repairing a ship in a dry dock','counting fish in a shoal','购买食品和家庭用品属于 shopping。',1,'context')]);
P('shopping centre','Shopping centre combines shopping and centre; it means a group of stores and services in one place, often with parking and covered walkways.',C('shopping centre.s1','购物中心；商业中心','The shopping centre stayed open late, and visitors walked between its stores under a covered roof.','购物中心延长了营业时间，顾客在有顶棚的通道下穿梭于各家商店。','The shopping centre stayed open late / with covered walkways / between stores.','shopping centre.s1 指集中多家商店和服务设施的区域。','多家商店由有顶通道连接。'),M('The shopping centre was a single isolated boat with no stores, services, or access for visitors.','The shopping centre grouped many stores and services in one place.','孤立的船只不具备购物中心的商店和服务集合。','meaning'),[q('How did visitors walk between stores?','under a covered roof','through open water','along a ship’s deck','顾客沿有顶棚的通道在商店间行走。',1,'context'),q('When did the centre stay open?','late','only before sunrise for one minute','not at all','购物中心延长了营业时间。',1,'context'),q('What is a shopping centre?','a place grouping shops and services together','a single shop assistant','a large group of fish','shopping centre 指集中多家商店和服务的商业中心。',1,'meaning'),q('Which place is a shopping centre?','a complex of stores linked by covered walkways','one small shop with no neighboring services','a harbor used only for shipbuilding','由有顶棚通道连接多家商店的综合体是 shopping centre。',1,'context')]);
P('shore','Shore (the coast noun) comes from Old English scor (“coast, boundary”); the verb in shore up has a separate history and means support something at risk.',[C('shore.s1','岸；滨；海滨','The children collected smooth stones along the shore of the lake before sunset.','日落前，孩子们沿湖岸捡拾光滑的石头。','The children collected stones / along the lake shore / before sunset.','shore.s1 指海、湖或宽阔河流边缘的陆地。','湖岸是陆地与水的边界。'),C('shore.s2','支撑；加固（常与 up 连用）','Workers used steel beams to shore up the cracked wall until a permanent repair could be made.','工人用钢梁支撑开裂的墙体，直到能够进行永久修缮。','Workers used steel beams / to shore up the wall / until repairs were made.','shore.s2 作动词，常与 up 连用，指支撑可能倒塌或失败的事物。','钢梁暂时支撑墙体。')],M('Workers shored up the cracked wall by removing its supports and pushing it toward collapse.','Workers shored up the cracked wall with steel beams.','拆除支撑会使墙更危险，不是加固。','meaning'),[q('Where did the children collect stones?','along the lake shore','inside a shopping centre','on a shipyard roof','孩子们沿湖岸收集石头。',1,'context'),q('What did workers use to shore up the wall?','steel beams','a shoelace','a sheet of rain','工人用钢梁支撑开裂的墙。',2,'context'),q('What is shore in the lake example?','the land along the edge of a lake','a place where ships are repaired','a group of coastal birds','湖岸例句中的 shore 指湖边的陆地。',1,'meaning'),q('What does shore up mean?','support something that may fall or fail','collect stones from a beach','move goods from one country to another','shore up 指支撑可能倒塌或失败的事物。',2,'meaning')]);
P('shorebird','Shorebird combines shore and bird; it names a bird that lives and feeds on coasts, beaches, or mudflats.',C('shorebird.s1','岸边涉禽','At low tide, a shorebird searched the exposed mudflat for small crabs and worms.','退潮时，一只岸边涉禽在露出的泥滩上寻找小蟹和蠕虫。','At low tide, a shorebird searched / the exposed mudflat / for crabs and worms.','shorebird.s1 指在海岸、海滩或泥滩生活觅食的鸟。','鸟在退潮后的泥滩觅食。'),M('The shorebird fed on mountain snow far inland and never visited a coast or mudflat.','The shorebird searched the coastal mudflat for small animals.','岸边涉禽在海岸和泥滩附近生活觅食。','meaning'),[q('When did the shorebird search for food?','at low tide','during a snowstorm at the summit','inside a shopping centre','岸边涉禽在退潮时寻找食物。',1,'context'),q('What did it look for on the mudflat?','small crabs and worms','shoelaces and shirts','metal ship plates','鸟在泥滩上寻找小蟹和蠕虫。',1,'context'),q('What is a shorebird?','a bird that lives and feeds on coasts or mudflats','a fish swimming in a shoal','a bird kept in a sheepfold','shorebird 指在海岸或泥滩生活觅食的鸟。',1,'meaning'),q('Which animal is a shorebird?','a bird searching a tidal mudflat for food','a bird living only in a dry mountain cave','a fish swimming near a harbor','在潮汐泥滩觅食的鸟是 shorebird。',1,'context')]);
P('shoreline','Shoreline combines shore and line; it means the boundary where a body of water meets land.',C('shoreline.s1','水岸交界线','The surveyors marked the shoreline before the reservoir was filled with water.','水库蓄水前，测量人员标出了水岸交界线。','The surveyors marked the shoreline / before the reservoir / was filled.','shoreline.s1 指水体与陆地相接的边缘线。','蓄水前标记未来水岸。'),M('The surveyors marked the shoreline at the center of the dry reservoir, far from any land-water boundary.','The surveyors marked the edge where reservoir water would meet the land.','远离水陆交界处的中心不是 shoreline。','meaning'),[q('When did surveyors mark the shoreline?','before the reservoir was filled','after the reservoir had been drained for a century','during a shipwreck','测量人员在水库蓄水前标记水岸线。',1,'context'),q('What boundary did they mark?','where water would meet land','the center of a dry reservoir','the edge of a shirt','他们标出未来水体与陆地相接的边界。',1,'context'),q('What is a shoreline?','the edge where a body of water meets land','the deep center of a lake','a bird feeding in mud','shoreline 指水体与陆地相接的边缘线。',1,'meaning'),q('Which line is a shoreline?','the boundary between the lake and the beach','a line painted down a road far from water','the seam along a shirt collar','湖水与沙滩相接的边界线是 shoreline。',1,'context')]);
P('short','Short comes from Old English sceort; it can describe small length or height, brief duration, insufficient supply, or stopping before an expected point.',[C('short.s1','短的；矮的','The short ladder reached only halfway up the wall, so the painter fetched a taller one.','这把短梯子只够到墙的一半，因此油漆工又拿来一把更高的梯子。','The short ladder reached halfway / so the painter / fetched a taller one.','short.s1 指长度或高度较小的。','梯子高度不足。'),C('short.s2','短暂的','We had a short meeting before lunch and settled the delivery time in ten minutes.','午饭前我们开了个简短会议，十分钟内就敲定了送货时间。','We had a short meeting / before lunch / and settled the time quickly.','short.s2 指持续时间不长的。','会议只持续十分钟。'),C('short.s3','短缺的；不足的','The rescue team was short of blankets after more families arrived at the shelter.','更多家庭抵达避难所后，救援队的毯子不够用了。','The rescue team was short of blankets / after more families / arrived.','short.s3 指没有足够数量的某物。','毯子数量无法满足需求。'),C('short.s4','突然；不及地','The runner stopped short when a shorebird crossed the path in front of her.','一只岸边涉禽穿过跑道时，跑者突然停了下来。','The runner stopped short / when a shorebird / crossed the path.','short.s4 作副词，指在预期位置前突然停止或未达到目标。','跑者在鸟前突然停下。')],M('The meeting was short because it lasted all afternoon and continued well past midnight.','The meeting was short because it lasted only ten minutes.','持续整下午并过午夜的会议不短暂。','meaning'),[q('How far did the short ladder reach?','halfway up the wall','above the roof','to the shoreline','短梯子只够到墙的一半。',1,'context'),q('How long was the meeting?','ten minutes','all afternoon','two full weeks','简短会议持续了十分钟。',2,'context'),q('What was the rescue team short of?','blankets','shorebirds','wooden ladders','避难所的救援队毯子不够。',3,'context'),q('Why did the runner stop short?','a shorebird crossed the path','she had reached the finish line long ago','the ladder was too tall','岸边涉禽穿过跑道时，跑者突然停下。',4,'context')]);
P('short of','Short of is a phrase with short meaning “not having enough”; short of is used with be to say something is lacking.',C('short of.s1','缺少；不够','The repair crew was short of bolts, so the supervisor delayed the bridge inspection until more arrived.','维修队缺少螺栓，主管因此把桥梁检查推迟到补货之后。','The crew was short of bolts / so the inspection / was delayed.','short of.s1 指所需或想要的数量不足。','螺栓数量不足以继续维修。'),M('The repair crew was short of bolts, so it had far more than the project could ever use.','The repair crew was short of bolts and needed more before continuing.','数量远远过剩与不足相反。','meaning'),[q('What was the repair crew short of?','bolts','sheepfolds','shopping centres','维修队缺少螺栓。',1,'context'),q('What did the supervisor do because supplies were lacking?','delayed the bridge inspection','started the inspection immediately with no delay','sent the crew to a shoe shop','主管因缺少螺栓而推迟检查。',1,'context'),q('What does short of mean?','not having as much as is needed','having far more than is needed','being physically shorter than a worker','short of 指所需数量不足。',1,'meaning'),q('Which situation is short of staff?','a shop needs three assistants but only one is working','a shop has twice as many assistants as needed','a shop has enough assistants for every shift','商店需要三名店员却只有一人上班，说明人手不足。',1,'context')]);
P('short-range','Short-range combines short and range; it describes something covering a small distance or a near time horizon.',[C('short-range.s1','短射程的；短距离的','The short-range radio connected the search team across the valley but could not reach the distant base.','短距离无线电能连接山谷两侧的搜救队，却无法联络远处基地。','The short-range radio connected the team / across the valley / but not the distant base.','short-range.s1 指作用或覆盖的距离较短的。','无线电只能覆盖山谷范围。'),C('short-range.s1','近期的；短期的','The council adopted a short-range plan to repair the damaged pier before winter.','市议会制定了一个近期计划，在冬天前修复受损码头。','The council adopted a short-range plan / to repair the pier / before winter.','short-range.s1 也可指面向不久将来的计划或预测。','计划安排在冬季之前完成。')],M('The short-range radio reached a station thousands of miles away across several oceans.','The short-range radio connected nearby teams but could not reach the distant base.','超远距离通讯不符合短距离设备的范围。','meaning'),[q('Where could the short-range radio connect the team?','across the valley','across several oceans to a distant continent','inside a shopping centre only','短距离无线电能连接山谷两侧的队员。',1,'context'),q('When did the council plan to repair the pier?','before winter','in a century','after the pier had disappeared','近期计划安排在冬天前修复码头。',1,'context'),q('What does short-range mean about the radio?','covering only a small distance','covering a whole continent','having no communication function','无线电句中的 short-range 指覆盖距离短。',1,'meaning'),q('What does short-range mean about the council’s plan?','aimed at the near future','designed for the next century','covering a very large physical area','计划句中的 short-range 指近期的、短期的。',1,'meaning')]);
})();
